const pageText={
ar:{top:"المعرفة العملية للفلاح والمربي الجزائري",brand:"الزراعة بذكاء",home:"الرئيسية",about:"من نحن",services:"مجالاتنا",knowledge:"المعرفة الفلاحية",tools:"حاسبات المشاريع",contact:"اتصل بنا",eyebrow:"مكتبة SA AgriAI / 01",title:"المعرفة التي<br><em>تنمّي مشروعك.</em>",lead:"مقالات عملية مبنية على مراجع فنية وبحثية، مع مراعاة ظروف الإنتاج والمناخ في الجزائر. نبدأ بالأغنام ونتوسع إلى مختلف الحيوانات والمحاصيل.",statArticles:"مقالاً ودليلاً عملياً",statAreas:"مجالات معرفية",statLang:"لغات للموقع",searchPlaceholder:"ابحث عن مقال أو موضوع أو مشكلة...",all:"الكل",sheep:"الأغنام",small:"الحيوانات الصغيرة",birds:"الطيور",crops:"الزراعة",note:"<strong>تركيز خاص على الأغنام:</strong> سلسلة متدرجة للسلالات الجزائرية والتغذية والتكاثر ورعاية المواليد والصحة وإدارة القطيع.",empty:"لم نعثر على مقالات تطابق بحثك.",sourceNote:"نعتمد على مراجع جامعية وفنية وهيئات متخصصة، ونوضح متى تكون النصيحة عامة أو تحتاج إلى تشخيص بيطري أو توصية محلية.",footer:"نزرع المعرفة لنحصد مستقبلاً أفضل.",back:"العودة للأعلى",rights:"جميع الحقوق محفوظة.",sources:"مراجع للقراءة",disclaimer:"هذه معلومات تثقيفية عامة وليست تشخيصاً أو وصفة علاجية. استشر طبيباً بيطرياً عند المرض أو النفوق أو تعسر الولادة.",read:"اقرأ المقال",min:"دقائق",categories:{sheep:"الأغنام",ruminants:"الماعز والأبقار والإبل",working:"الخيول والحمير والبغال",small:"الأرانب والحيوانات الصغيرة",birds:"الدواجن والطيور",bees:"النحل",fish:"الأسماك",crops:"الزراعة"}},
fr:{top:"Des conseils pratiques pour les agriculteurs et éleveurs algériens",brand:"Agriculture intelligente",home:"Accueil",about:"À propos",services:"Nos domaines",knowledge:"Savoir agricole",tools:"Calculateurs",contact:"Contact",eyebrow:"Bibliothèque SA AgriAI / 01",title:"Le savoir qui<br><em>fait grandir votre activité.</em>",lead:"Des articles pratiques fondés sur des références techniques et scientifiques, adaptés aux réalités algériennes. Nous commençons par l’élevage ovin.",statArticles:"articles et guides pratiques",statAreas:"Domaines",statLang:"Langues du site",searchPlaceholder:"Rechercher un article, un sujet ou un problème...",all:"Tout",sheep:"Ovins",small:"Petits élevages",birds:"Volailles",crops:"Cultures",note:"<strong>Focus sur les ovins :</strong> races algériennes, alimentation, reproduction, soins aux agneaux, santé et conduite du troupeau.",empty:"Aucun article ne correspond à votre recherche.",sourceNote:"Nous utilisons des références universitaires et techniques et précisons quand un conseil nécessite un diagnostic vétérinaire ou une recommandation locale.",footer:"Cultiver le savoir pour un avenir meilleur.",back:"Retour en haut",rights:"Tous droits réservés.",sources:"Références",disclaimer:"Informations éducatives générales, sans valeur de diagnostic ni de prescription. Consultez un vétérinaire en cas de maladie, mortalité ou mise bas difficile.",read:"Lire l’article",min:"min",categories:{sheep:"Ovins",ruminants:"Caprins, bovins et camélidés",working:"Chevaux, ânes et mulets",small:"Lapins et petits élevages",birds:"Volailles et oiseaux",bees:"Apiculture",fish:"Pisciculture",crops:"Cultures"}},
en:{top:"Practical knowledge for Algerian farmers and livestock keepers",brand:"Smart agriculture",home:"Home",about:"About",services:"Our focus",knowledge:"Agri knowledge",tools:"Project calculators",contact:"Contact",eyebrow:"SA AgriAI Library / 01",title:"Knowledge that<br><em>grows your farm.</em>",lead:"Practical articles based on technical and research references, with Algeria’s production conditions in mind. We begin with sheep farming and expand across livestock and crops.",statArticles:"practical articles and guides",statAreas:"Knowledge areas",statLang:"Site languages",searchPlaceholder:"Search articles, topics or problems...",all:"All",sheep:"Sheep",small:"Small livestock",birds:"Poultry",crops:"Crops",note:"<strong>Special focus on sheep:</strong> Algerian breeds, feeding, reproduction, lamb care, health and flock management.",empty:"No articles match your search.",sourceNote:"We use academic and technical references and distinguish general guidance from issues requiring local veterinary advice.",footer:"Growing knowledge for a better future.",back:"Back to top",rights:"All rights reserved.",sources:"Further reading",disclaimer:"General educational information, not a diagnosis or treatment prescription. Contact a veterinarian for illness, deaths or difficult births.",read:"Read article",min:"min",categories:{sheep:"Sheep",ruminants:"Goats, cattle and camels",working:"Horses, donkeys and mules",small:"Rabbits and small livestock",birds:"Poultry and birds",bees:"Beekeeping",fish:"Fish farming",crops:"Crops"}}};
const articles=[
{id:"breeds",cat:"sheep",mins:6,src:[["Practical sheep management in Eastern Algeria (2024)","https://eprints.science-line.com/id/eprint/1176/"],["Algeria National Inventory 2024 – sheep breeds","https://unfccc.int/sites/default/files/resource/NID_Algeria_2024_Final-DZ.pdf"]],ar:{title:"السلالات المحلية للأغنام في الجزائر: كيف تختار القطيع؟",excerpt:"أولاد جلال والرمبي والحمراء وغيرها: الاختيار الصحيح يرتبط بالمنطقة والمرعى والهدف الإنتاجي.",body:[["اختيار السلالة","تختلف السلالات في البنية والتأقلم والصفات الإنتاجية. لا توجد سلالة واحدة هي الأفضل لكل المربين؛ فالاختيار يتأثر بالمناخ والمرعى وتوفر العلف والهدف من التربية، سواء اللحم أو الحليب أو المحافظة على سلالة محلية."],["أمثلة جزائرية","من السلالات المعروفة في المراجع الجزائرية: أولاد جلال، الرّمبي، الحمراء والبرابرية، إلى جانب سلالات محلية أخرى. قبل الشراء، عاين الأرجل والأسنان والحالة الجسمية والضرع، واطلب سجل الولادات والعلاجات، واعزل الحيوانات الجديدة واطلب فحصاً بيطرياً."]]},fr:{title:"Races ovines locales en Algérie : choisir son troupeau",excerpt:"Ouled Djellal, Rembi, Hamra et autres : le choix dépend de la région, des parcours et de l’objectif.",body:[["Choisir une race","Les races diffèrent par leur morphologie, leur adaptation et leurs aptitudes. Aucune race ne convient à toutes les exploitations : climat, pâturage, aliments disponibles et objectif de production doivent guider le choix."],["Exemples algériens","Les références algériennes citent notamment Ouled Djellal, Rembi, Hamra et Barbarine. Avant l’achat, examinez les aplombs, les dents, l’état corporel et la mamelle. Demandez les historiques, isolez les nouveaux animaux et prévoyez un examen vétérinaire."]]},en:{title:"Local sheep breeds in Algeria: choosing a flock",excerpt:"Ouled Djellal, Rembi, Hamra and others: choice should match region, grazing and production goals.",body:[["Choosing a breed","Breeds differ in body type, adaptation and production traits. No single breed suits every farm: climate, grazing, feed availability and production goals should guide the choice."],["Algerian examples","Algerian references include Ouled Djellal, Rembi, Hamra and Barbarine, among other local populations. Before buying, check legs, teeth, body condition and udder health. Ask for records, quarantine new stock and arrange a veterinary check."]]}},
{id:"feed",cat:"sheep",mins:7,src:[["Merck Veterinary Manual – Nutrition of Sheep","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep/nutrition-of-sheep"],["Sheep feeding strategies in Tizi Ouzou, Algeria","https://ressources.ciheam.org/web/controleurFrontal.php?IDPDF=00007832&action=afficherArticle"]],ar:{title:"تغذية الأغنام: الموازنة بين المرعى والعلف",excerpt:"الماء والعلف الخشن أساس التغذية، وتُعدّل المكملات حسب الحمل والرضاعة والنمو.",body:[["الأساس اليومي","وفّر ماءً نظيفاً باستمرار وعلفاً خشناً جيداً مثل التبن أو المرعى المناسب. استخدم المكملات عند الحاجة، وزِد الحبوب والمركزات تدريجياً لتقليل اضطرابات الهضم. تجنب الأعلاف المتعفنة أو الملوثة."],["تختلف الاحتياجات","النعجة الجافة ليست كالنعجة في أواخر الحمل أو بداية الرضاعة، كما تختلف احتياجات الحملان والكباش. راقب حالة الجسم والشهية والاجترار والبراز، ولا تعتمد خلطة ثابتة لكل القطعان؛ فالموارد تختلف بين السهوب والجبال والمناطق الجافة."]]},fr:{title:"Alimentation des ovins : équilibrer pâturage et compléments",excerpt:"L’eau et les fourrages sont la base ; les compléments dépendent de la gestation, lactation et croissance.",body:[["La base quotidienne","Fournissez de l’eau propre en permanence et un fourrage de qualité. Les compléments répondent aux besoins identifiés. Augmentez progressivement les céréales et concentrés. Écartez les aliments moisis ou contaminés."],["Des besoins différents","Une brebis vide, en fin de gestation ou en lactation n’a pas les mêmes besoins. Surveillez l’état corporel, l’appétit, la rumination et les fèces. Une ration doit être adaptée aux ressources locales, différentes entre steppes, montagnes et zones arides."]]},en:{title:"Sheep nutrition: balancing grazing and supplementary feed",excerpt:"Water and forage are the foundation; supplements depend on pregnancy, lactation and growth.",body:[["Daily foundation","Provide clean water at all times and good-quality forage. Use supplements to meet identified needs and increase grain or concentrates gradually. Never feed mouldy or contaminated material."],["Needs change by stage","A dry ewe, a ewe in late pregnancy and a lactating ewe have different requirements. Monitor body condition, appetite, rumination and manure. Adapt rations to local resources across steppe, mountain and arid areas."]]}},
{id:"lambing",cat:"sheep",mins:6,src:[["UF/IFAS – Foundational small ruminant management","https://ask.ifas.ufl.edu/publication/VM272"],["Practical sheep management in Eastern Algeria","https://eprints.science-line.com/id/eprint/1176/"]],ar:{title:"الاستعداد للولادة ورعاية الخروف في أيامه الأولى",excerpt:"تهيئة مكان نظيف، التأكد من الرضاعة المبكرة، ومعرفة علامات الخطر التي تستدعي الطبيب.",body:[["قبل الولادة","جهّز مكاناً نظيفاً وجافاً وهادئاً مع تهوية جيدة دون تيارات هواء مباشرة. راقب النعاج القريبة من الولادة وسجّل مواعيد التلقيح والحالة الصحية."],["بعد الولادة","راقب تنفس الخروف وقدرته على الوقوف والوصول إلى الضرع. تأكد من حصوله على اللبأ في الساعات الأولى، وافحص الضرع وتابع الأم والمولود. اطلب الطبيب عند تعسر الولادة أو النزيف غير الطبيعي أو ضعف المولود أو عجزه عن الرضاعة. لا تسحب الجنين بالقوة ولا تعطِ أدوية دون توجيه بيطري."]]},fr:{title:"Préparer l’agnelage et soigner l’agneau nouveau-né",excerpt:"Préparer un espace propre, vérifier la prise du colostrum et reconnaître les urgences vétérinaires.",body:[["Avant l’agnelage","Préparez un espace calme, propre et sec, bien ventilé et sans courant d’air direct. Surveillez les brebis proches du terme et notez les dates et observations sanitaires."],["Après la naissance","Vérifiez la respiration, la capacité à se lever et à téter. Assurez-vous que l’agneau reçoit rapidement le colostrum. Appelez le vétérinaire en cas de dystocie, saignement anormal, grande faiblesse ou incapacité à téter. Ne tirez pas avec force et n’administrez pas de médicaments sans avis."]]},en:{title:"Preparing for lambing and caring for newborn lambs",excerpt:"Prepare a clean lambing area, check early colostrum intake and recognize veterinary emergencies.",body:[["Before lambing","Prepare a quiet, clean, dry area with good ventilation and no direct draughts. Monitor near-term ewes and record dates and health observations."],["After birth","Check breathing, ability to stand and suckle. Make sure the lamb receives colostrum promptly. Call a veterinarian for difficult birth, abnormal bleeding, severe weakness or inability to suckle. Never pull forcefully or give medicines without professional advice."]]}},
{id:"rabbit",cat:"small",mins:5,src:[["FAO – Try the rabbit: a practical guide","https://www.fao.org/family-farming/detail/en/c/1619556/"],["FAO – Rabbit breeding and feeding","https://www.fao.org/4/t0690e/t0690e0a.htm"]],ar:{title:"تربية الأرانب: المسكن والتغذية والتكاثر",excerpt:"ابدأ بأرانب سليمة، ومسكن جاف مهوّى، وماء دائم، وسجل للتزاوج والولادات.",body:[["المسكن","يجب أن يكون المكان جافاً ونظيفاً ومهوّى ومحميّاً من الشمس المباشرة والرياح والحيوانات المفترسة. وفّر الظل والماء، ونظّف المشارب والمعالف بانتظام."],["التغذية والتكاثر","استخدم علفاً متوازناً مناسباً للأرانب مع ألياف جيدة وماء متاح دائماً. لا تغيّر العليقة فجأة ولا تقدم نباتات مجهولة أو متعفنة. سجّل التزاوج والولادة وعدد الخلفات، وراقب الشهية والبراز والنشاط يومياً."]]},fr:{title:"Élevage du lapin : logement, alimentation et reproduction",excerpt:"Démarrer avec des animaux sains, un logement sec et ventilé, de l’eau et des registres.",body:[["Logement","Le local doit être sec, propre, ventilé et protégé du soleil direct, du vent et des prédateurs. Prévoyez ombre et eau et nettoyez les abreuvoirs et mangeoires."],["Alimentation et reproduction","Utilisez un aliment équilibré avec des fibres de qualité et de l’eau en permanence. Évitez les changements brusques et les plantes inconnues ou moisies. Notez les saillies et mises bas, et surveillez chaque jour l’appétit, les fèces et l’activité."]]},en:{title:"Rabbit keeping: housing, feeding and breeding",excerpt:"Start with healthy stock, dry ventilated housing, constant water and breeding records.",body:[["Housing","Keep housing dry, clean, ventilated and protected from direct sun, wind and predators. Provide shade and water and clean drinkers and feeders regularly."],["Feeding and breeding","Use balanced rabbit feed with good-quality fibre and constant access to water. Avoid sudden diet changes and unknown or mouldy plants. Record mating and kindling, and check appetite, droppings and activity daily."]]}},
{id:"quail",cat:"birds",mins:4,src:[["FAO – Poultry production resources","https://www.fao.org/poultry-production-products/production/en/"]],ar:{title:"تربية السمان: أساسيات الانطلاق وإدارة القطيع",excerpt:"حدد هدف المشروع واحسب التكاليف، ثم اضبط التحضين والتهوية والعلف والماء.",body:[["قبل الشراء","حدد الهدف: بيض التفريخ أو بيض الاستهلاك أو اللحم. احسب تكاليف المسكن والعلف والتدفئة والكهرباء والماء والتسويق قبل شراء الطيور."],["التحضين والمتابعة","تحتاج الكتاكيت إلى حرارة تناسب عمرها وتُخفض تدريجياً وفق سلوك الطيور وإرشاد فني. تجنب التكدس والتيارات الهوائية. استخدم علفاً متوازناً للمرحلة، وسجّل استهلاك العلف وإنتاج البيض والنفوق."]]},fr:{title:"Élevage de cailles : démarrage et conduite du lot",excerpt:"Définir l’objectif et les coûts, puis gérer démarrage, ventilation, alimentation et eau.",body:[["Avant l’achat","Définissez l’objectif : œufs à couver, œufs de consommation ou viande. Calculez les coûts du logement, de l’aliment, du chauffage, de l’électricité, de l’eau et de la vente."],["Démarrage et suivi","Les poussins ont besoin d’une température adaptée à leur âge, abaissée progressivement selon leur comportement et des conseils techniques. Évitez la surdensité et les courants d’air. Notez aliment, ponte et mortalité."]]},en:{title:"Quail farming: getting started and flock management",excerpt:"Define the goal and costs, then manage brooding, ventilation, feed and water.",body:[["Before buying","Define the goal: hatching eggs, table eggs or meat. Budget for housing, feed, heating, electricity, water and marketing."],["Brooding and monitoring","Chicks need a temperature suited to their age, reduced gradually according to behaviour and reliable guidance. Avoid overcrowding and draughts. Record feed use, egg output and mortality."]]}},
{id:"ducks",cat:"birds",mins:5,src:[["FAO – Poultry production resources","https://www.fao.org/poultry-production-products/production/en/"]],ar:{title:"تربية البط والإوز: الماء والمسكن والتغذية",excerpt:"مأوى جاف وتهوية جيدة وماء شرب نظيف؛ حوض السباحة لا يعوض ماء الشرب.",body:[["المسكن والماء","وفّر مأوى جافاً جيد التهوية يحمي الطيور من المطر والحرارة والمفترسات، مع فرشة تمتص الرطوبة. يجب أن يتوفر ماء شرب نظيف دائماً في أوعية تسمح بغمر المنقار. إذا وفرت حوضاً، فنظفه وصرف مياهه بانتظام."],["التغذية والوقاية","استخدم علفاً متوازناً مناسباً للنوع والعمر، ولا تجعل الخبز وبقايا الطعام الغذاء الأساسي. نظّف المشارب والمعالف، وقلل الاختلاط بالطيور البرية، واعزل الطيور المريضة واستشر الطبيب بشأن الوقاية المحلية."]]},fr:{title:"Élever canards et oies : eau, logement et alimentation",excerpt:"Un abri sec, une bonne ventilation et de l’eau potable propre ; le bassin ne remplace pas l’abreuvoir.",body:[["Logement et eau","Prévoyez un abri sec et ventilé, protégé de la pluie, de la chaleur et des prédateurs, avec une litière absorbante. L’eau potable propre doit être disponible en permanence. Nettoyez et vidangez régulièrement tout bassin."],["Alimentation et prévention","Utilisez un aliment équilibré adapté à l’espèce et à l’âge. Le pain et les restes ne doivent pas constituer la ration de base. Nettoyez les équipements, limitez les contacts avec les oiseaux sauvages et isolez les sujets malades."]]},en:{title:"Raising ducks and geese: water, housing and feeding",excerpt:"A dry shelter, good ventilation and clean drinking water; a pond does not replace a drinker.",body:[["Housing and water","Provide a dry, ventilated shelter protected from rain, heat and predators, with absorbent bedding. Clean drinking water must always be available. Drain and clean any pond regularly."],["Feeding and prevention","Use balanced feed suited to species and age. Bread and scraps should not be the main ration. Clean equipment, limit contact with wild birds and isolate sick birds."]]}},
{id:"ostrich",cat:"birds",mins:5,src:[["Poultry Science (2025) – Ostrich nutrition review","https://pmc.ncbi.nlm.nih.gov/articles/PMC12356471/"]],ar:{title:"تربية النعام: مشروع متخصص يحتاج إلى دراسة مسبقة",excerpt:"النعام يحتاج إلى مساحة وسياج آمن وتغذية حسب العمر وإدارة دقيقة للبيض والتحضين.",body:[["قبل الاستثمار","ادرس السوق المحلي والطلب، وتحقق من القوانين والتراخيص ومتطلبات نقل الحيوانات. يحتاج النعام إلى مساحة واسعة وسياج قوي ومرافق آمنة، وليس مناسباً لكل مزرعة صغيرة."],["التغذية والتفريخ","تتغير الاحتياجات بين الفراخ والطيور النامية والبالغة والمنتجة. تؤكد المراجعات العلمية أهمية توازن الطاقة والبروتين والألياف والمعادن. كما أن نظافة الحاضنة وضبط الحرارة والرطوبة والتهوية عوامل مهمة؛ استعن بخبرة متخصصة وطبيب بيطري."]]},fr:{title:"Élevage d’autruches : une activité spécialisée à étudier",excerpt:"L’autruche exige de l’espace, des clôtures sûres, une alimentation adaptée à l’âge et une incubation maîtrisée.",body:[["Avant d’investir","Étudiez le marché et vérifiez les règles, autorisations et conditions de transport. Les autruches nécessitent de grandes surfaces, des clôtures solides et des installations sûres."],["Alimentation et incubation","Les besoins diffèrent entre poussins, jeunes, adultes et reproducteurs. Les revues scientifiques soulignent l’équilibre énergétique, protéique, fibreux et minéral. L’hygiène de l’incubateur et le contrôle de la température, de l’humidité et de l’air sont essentiels."]]},en:{title:"Ostrich farming: a specialist venture requiring planning",excerpt:"Ostriches need space, secure fencing, age-specific feed and careful egg incubation management.",body:[["Before investing","Study local demand and verify rules, permits and animal transport requirements. Ostriches need substantial space, strong fencing and safe facilities."],["Feeding and incubation","Needs differ between chicks, growers, adults and breeders. Research reviews emphasize balanced energy, protein, fibre and minerals. Incubator hygiene and control of temperature, humidity and airflow are essential."]]}},
{id:"irrigation",cat:"crops",mins:6,src:[["ITCMI – Practical guides and technical sheets","https://itcmi-dz.org/guides.html"],["FAO – Water management","https://www.fao.org/land-water/water/water-management/en/"]],ar:{title:"إدارة مياه الري: خطوات عملية لتقليل الهدر",excerpt:"اعرف التربة والمحصول، وراقب رطوبة منطقة الجذور والتسربات بدلاً من الري حسب العادة.",body:[["اعرف أرضك","تختلف حاجة الطماطم عن الزيتون والحبوب والأشجار المثمرة، كما تختلف حسب مرحلة النمو والتربة والطقس. افحص قوام التربة وعمق الجذور ومصدر المياه قبل تحديد برنامج الري."],["الري بالتنقيط والمتابعة","يمكن أن يوصل التنقيط الماء قرب الجذور إذا صُممت الشبكة جيداً ونُظفت المرشحات ورُوقب الضغط والتسرب. افحص رطوبة التربة في عمق الجذور؛ فالري الزائد يهدر الماء وقد يغسل العناصر الغذائية. سجّل مواعيد الري ومدته ونتائج المحصول."]]},fr:{title:"Gestion de l’irrigation : réduire le gaspillage",excerpt:"Connaître le sol et la culture, puis contrôler l’humidité racinaire et les fuites au lieu d’arroser par habitude.",body:[["Connaître la parcelle","Les besoins de la tomate, de l’olivier, des céréales et des arbres fruitiers varient selon le stade, le sol et la météo. Évaluez la texture du sol, la profondeur des racines et la source d’eau."],["Goutte-à-goutte et suivi","Le goutte-à-goutte peut apporter l’eau près des racines si le réseau est bien conçu et entretenu. Nettoyez les filtres et contrôlez pression et fuites. Vérifiez l’humidité racinaire : l’excès d’eau gaspille et peut lessiver les nutriments. Notez les irrigations et les résultats."]]},en:{title:"Irrigation management: practical ways to reduce waste",excerpt:"Understand the soil and crop, then monitor root-zone moisture and leaks instead of watering by habit.",body:[["Know the field","Tomatoes, olives, cereals and fruit trees have different needs depending on growth stage, soil and weather. Check soil texture, rooting depth and water source."],["Drip irrigation and monitoring","Drip can deliver water near roots when the system is designed and maintained correctly. Clean filters and check pressure and leaks. Assess root-zone moisture: over-irrigation wastes water and can leach nutrients. Record irrigation and crop results."]]}}
];

const extraArticles=[
{ id:"goats",cat:"ruminants",mins:7,src:[["FAO – Livestock production","https://www.fao.org/livestock-systems/en/"]],ar:{title:"تربية الماعز في الجزائر: اختيار القطيع وإدارته",excerpt:"دليل عملي لاختيار الأمهات والفحول، وتجهيز الحظيرة وتنظيم التغذية والتكاثر.",body:[["اختيار الحيوانات والمكان","اختر حيوانات نشيطة ذات أرجل سليمة وشهية جيدة وضرع طبيعي، واسأل عن تاريخ الولادات والأمراض. جهّز مأوى جافاً جيد التهوية يحمي من المطر والحرارة والرياح، مع مساحة للحركة وسياج آمن."],["التغذية والتكاثر","وفّر الماء النظيف والعلف الخشن الجيد، وكيّف المكملات حسب العمر والحمل والرضاعة. سجّل التلقيح والولادات والمواليد، وافصل الحيوان الجديد مؤقتاً واطلب برنامج الوقاية من طبيب بيطري محلي."]]},fr:{title:"Élevage caprin en Algérie : choisir et gérer le troupeau",excerpt:"Choix des reproducteurs, logement, alimentation et suivi de la reproduction.",body:[["Choix et logement","Choisissez des animaux alertes, avec des aplombs sains, un bon appétit et une mamelle normale. Demandez l’historique des mises bas et maladies. Prévoyez un abri sec, ventilé, protégé des intempéries, avec espace et clôture sûre."],["Alimentation et reproduction","Fournissez de l’eau propre et du fourrage de qualité ; adaptez les compléments à l’âge, la gestation et la lactation. Notez saillies, mises bas et chevreaux. Isolez les nouveaux animaux et établissez un plan sanitaire avec un vétérinaire local."]]},en:{title:"Goat farming in Algeria: choosing and managing a herd",excerpt:"A practical guide to breeding stock, housing, feeding and reproduction records.",body:[["Choosing animals and housing","Choose alert animals with sound legs, good appetite and a normal udder. Ask about kidding and disease history. Provide a dry, ventilated shelter protected from heat, rain and wind, with room to move and secure fencing."],["Feeding and breeding","Provide clean water and good forage; adapt supplements to age, pregnancy and lactation. Record mating, kidding and offspring. Quarantine new arrivals and agree a local health plan with a veterinarian."]]}},
{ id:"dairy-cows",cat:"ruminants",mins:8,src:[["FAO – Dairy production and products","https://www.fao.org/dairy-production-products/en/"]],ar:{title:"أساسيات تربية الأبقار الحلوب وإدارة الحليب",excerpt:"النظافة والتغذية والماء وسجل الإنتاج عناصر أساسية لصحة البقرة وجودة الحليب.",body:[["الحظيرة والروتين","وفّر فرشة جافة ومكاناً نظيفاً للحلب وماءً متاحاً باستمرار. نظّف الضرع والأدوات وفق إجراءات صحية، واحفظ الحليب بسرعة في ظروف تبريد مناسبة. راقب الشهية والاجترار والحركة وإنتاج الحليب يومياً."],["العليقة والمتابعة","تحتاج البقرة الحلوب إلى عليقة متوازنة من الأعلاف الخشنة والمركزة حسب وزنها ومرحلة الإدرار. لا تغيّر العلف فجأة. سجّل كمية الحليب والتلقيح والعلاجات، واستعن بطبيب بيطري عند التهاب الضرع أو الحمى أو انخفاض الإنتاج المفاجئ."]]},fr:{title:"Bases de l’élevage laitier et gestion du lait",excerpt:"Hygiène, ration, eau et suivi de production sont essentiels à la santé et à la qualité du lait.",body:[["Bâtiment et routine","Prévoyez une litière sèche, une aire de traite propre et de l’eau disponible en permanence. Nettoyez la mamelle et le matériel selon des règles d’hygiène et refroidissez rapidement le lait. Suivez chaque jour l’appétit, la rumination, la locomotion et la production."],["Ration et suivi","La vache laitière a besoin d’une ration équilibrée en fourrages et concentrés selon son poids et son stade de lactation. Évitez les changements brusques. Notez le lait, les inséminations et les soins ; contactez un vétérinaire en cas de mammite, fièvre ou chute soudaine de production."]]},en:{title:"Dairy cow basics and milk handling",excerpt:"Hygiene, balanced feed, water and production records support cow health and milk quality.",body:[["Housing and routine","Provide dry bedding, a clean milking area and constant access to water. Clean udders and equipment using hygienic procedures, and cool milk promptly under suitable conditions. Monitor appetite, rumination, movement and yield daily."],["Ration and monitoring","Dairy cows need a balanced forage-and-concentrate ration suited to body weight and lactation stage. Avoid sudden feed changes. Record milk yield, breeding and treatments; seek veterinary help for mastitis, fever or a sudden production drop."]]}},
{ id:"cattle-fattening",cat:"ruminants",mins:7,src:[["FAO – Animal production and health","https://www.fao.org/animal-production/en/"]],ar:{title:"تسمين العجول: التخطيط للعليقة والمدة والتسويق",excerpt:"نجاح التسمين يبدأ بشراء حيوان سليم ووزن البداية وحساب تكلفة الكيلوغرام المكتسب.",body:[["قبل الشراء","حدّد السوق المستهدف والوزن المطلوب ومدة الدورة ورأس المال المتاح. افحص الحيوان من حيث النشاط والتنفس والمشي والشهية، وسجّل الوزن وتاريخ الشراء. لا تشترِ اعتماداً على الشكل وحده."],["التدرج والحساب","قدّم العلف تدريجياً مع أساس من الألياف والماء النظيف، وتجنب الانتقال المفاجئ إلى كميات كبيرة من الحبوب. زن الحيوانات دورياً واحسب تكلفة العلف لكل زيادة وزن، وأدرج النقل والبيطرة والعمال والطاقة ضمن التكلفة."]]},fr:{title:"Engraissement des veaux : ration, durée et commercialisation",excerpt:"La réussite commence par un animal sain, un poids initial et le coût du gain de poids.",body:[["Avant l’achat","Définissez le marché, le poids cible, la durée du cycle et le budget. Vérifiez l’activité, la respiration, la démarche et l’appétit. Notez le poids et la date d’achat ; l’apparence seule ne suffit pas."],["Transition et calcul","Introduisez progressivement la ration, avec fibres et eau propre. Évitez une forte augmentation soudaine des céréales. Pesez régulièrement et calculez le coût alimentaire par gain de poids, en ajoutant transport, vétérinaire, main-d’œuvre et énergie."]]},en:{title:"Calf fattening: ration planning, cycle and marketing",excerpt:"A successful cycle starts with a healthy animal, starting weight and cost per kilogram gained.",body:[["Before purchase","Define the target market, finishing weight, cycle length and available capital. Check alertness, breathing, gait and appetite. Record weight and purchase date; appearance alone is not enough."],["Gradual transition and costing","Introduce feed gradually with adequate fibre and clean water. Avoid sudden large grain increases. Weigh animals regularly and calculate feed cost per unit of weight gain, including transport, veterinary care, labour and energy."]]}},
{ id:"camel",cat:"ruminants",mins:6,src:[["FAO – Animal production and health","https://www.fao.org/animal-production/en/"]],ar:{title:"مبادئ تربية الإبل وإدارة القطيع",excerpt:"الإبل متأقلمة مع البيئات الجافة، لكنها تحتاج إلى ماء ورعاية ومتابعة صحية منظمة.",body:[["المأوى والماء","وفّر مساحة آمنة ومظللة عند الحر ومصدات للرياح عند الحاجة، ومصدراً لماء نظيف. لا تفترض أن الإبل لا تحتاج إلى الماء؛ تتغير حاجتها حسب الحرارة والعمل والعلف والحالة الفسيولوجية."],["التغذية والصحة","اعتمد على موارد رعوية مناسبة وأعلاف مأمونة، وغيّر النظام الغذائي تدريجياً. راقب الشهية والحركة والجلد والحالة الجسمية، واعزل الحالات المريضة واستشر طبيباً بيطرياً لديه خبرة بالإبل."]]},fr:{title:"Principes de l’élevage camelin et conduite du troupeau",excerpt:"Adaptés aux zones arides, les dromadaires ont néanmoins besoin d’eau, de soins et d’un suivi sanitaire.",body:[["Abri et eau","Prévoyez un espace sûr, de l’ombre en période chaude et un accès à une eau propre. Les besoins en eau varient selon la température, le travail, l’alimentation et l’état physiologique."],["Alimentation et santé","Utilisez des ressources fourragères adaptées et des aliments sûrs, avec des transitions progressives. Surveillez l’appétit, la locomotion, la peau et l’état corporel. Isolez les malades et consultez un vétérinaire connaissant les camélidés."]]},en:{title:"Camel husbandry and herd management basics",excerpt:"Camels are adapted to dry environments but still need water, care and organized health monitoring.",body:[["Shelter and water","Provide a safe area, shade in hot weather and clean water. Water needs vary with temperature, workload, diet and physiological condition."],["Feeding and health","Use suitable grazing resources and safe feeds, changing diets gradually. Monitor appetite, movement, skin and body condition. Separate sick animals and consult a veterinarian experienced with camels."]]}},
{ id:"sheep-reproduction",cat:"sheep",mins:7,src:[["Merck Veterinary Manual – Sheep management","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep"]],ar:{title:"تنظيم تلقيح الأغنام وتحسين نتائج الولادات",excerpt:"تخطيط موسم التلقيح وسجل النعاج يساعد على تنظيم الولادات وتقليل المفاجآت.",body:[["قبل موسم التلقيح","افحص حالة النعاج الجسمية والأرجل والأسنان، ولا تدخل الحيوانات الضعيفة في موسم التلقيح قبل تقييمها. افحص الكباش ونشاطها وقدرتها على الحركة، وحدد فترة تلقيح وسجّل تواريخ إدخال الفحول وإخراجها."],["بعد التلقيح","راقب النعاج وسجّل الملاحظات والولادات السابقة. لا تعتمد على التخمين وحده لتحديد الحمل؛ اطلب التشخيص المناسب من مختص. خطط للعلف والمأوى والعمالة قبل موعد الولادة المتوقع."]]},fr:{title:"Organiser la lutte des brebis et améliorer les agnelages",excerpt:"Planifier la période de lutte et tenir des registres aide à organiser les mises bas.",body:[["Avant la lutte","Évaluez l’état corporel, les aplombs et les dents des brebis. Vérifiez les béliers, leur mobilité et leur état général. Définissez une période de lutte et notez les dates d’introduction et de retrait des mâles."],["Après la lutte","Suivez les brebis et consignez les observations et les mises bas précédentes. Ne confirmez pas une gestation par simple supposition ; demandez un diagnostic adapté. Préparez alimentation, abri et main-d’œuvre avant les dates prévues."]]},en:{title:"Planning sheep breeding and improving lambing outcomes",excerpt:"A defined mating season and ewe records help organize lambing and reduce surprises.",body:[["Before mating","Assess ewe body condition, feet and teeth. Check rams for mobility and general health. Set a breeding period and record when males join and leave the flock."],["After mating","Monitor ewes and record observations and previous lambings. Do not rely on guesswork to confirm pregnancy; arrange appropriate diagnosis. Plan feed, housing and labour before expected lambing."]]}},
{ id:"sheep-biosecurity",cat:"sheep",mins:6,src:[["Merck Veterinary Manual – Sheep health","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep"]],ar:{title:"الوقاية الصحية والأمن الحيوي في حظيرة الأغنام",excerpt:"العزل والنظافة ومراقبة القطيع والتنسيق مع البيطري تقلل انتقال الأمراض.",body:[["قواعد يومية","راقب الشهية والتنفس والحركة والبراز يومياً. وفّر تهوية وفرشة جافة وماءً نظيفاً، ونظّف المعالف والمشارب. أبعد الحيوانات المريضة عن السليمة وقلل ازدحام الحظيرة."],["الحيوانات الجديدة","اعزل المشتريات الجديدة فترة مناسبة يحددها الطبيب البيطري، وافحصها قبل خلطها بالقطيع. لا تشارك الأدوات بين المجموعات دون تنظيف، وسجّل اللقاحات والعلاجات والنفوق. لا تستخدم مضاداً حيوياً أو دواء طفيليات عشوائياً."]]},fr:{title:"Prévention sanitaire et biosécurité en bergerie",excerpt:"Quarantaine, hygiène et surveillance avec le vétérinaire réduisent la transmission des maladies.",body:[["Routine quotidienne","Surveillez chaque jour appétit, respiration, démarche et fèces. Assurez ventilation, litière sèche et eau propre ; nettoyez mangeoires et abreuvoirs. Séparez les malades et évitez la surdensité."],["Nouveaux animaux","Mettez les achats en quarantaine pendant une durée définie avec le vétérinaire et examinez-les avant mélange. Nettoyez le matériel entre lots et consignez vaccins, traitements et mortalité. N’utilisez pas d’antibiotiques ou d’antiparasitaires au hasard."]]},en:{title:"Sheep flock health and farm biosecurity",excerpt:"Quarantine, hygiene and routine monitoring with a veterinarian reduce disease spread.",body:[["Daily routine","Monitor appetite, breathing, movement and manure every day. Maintain ventilation, dry bedding and clean water; clean feeders and drinkers. Separate sick animals and avoid overcrowding."],["New arrivals","Quarantine purchased animals for a period agreed with a veterinarian and examine them before mixing. Clean equipment between groups and record vaccines, treatments and deaths. Never use antibiotics or parasite medicines at random."]]}},
{ id:"rabbit-housing",cat:"small",mins:6,src:[["FAO – The rabbit: husbandry, health and production","https://www.fao.org/4/x5082e/x5082e00.htm"]],ar:{title:"تجهيز مكان تربية الأرانب: التهوية والحرارة والنظافة",excerpt:"الحرارة والتهوية والأرضية النظيفة عوامل مؤثرة في صحة الأرانب وإنتاجها.",body:[["المكان والأقفاص","ضع الأقفاص في مكان هادئ جيد التهوية ومحمي من الشمس المباشرة والتيارات القوية. اجعل الأرضية جافة وسهلة التنظيف، ووفّر مساحة مناسبة للحركة مع حماية الأرجل من الأسطح المؤذية."],["النظافة والمراقبة","نظّف المشارب والمعالف بانتظام وأزل الفضلات والرطوبة. راقب الشهية والبراز والتنفس يومياً. عند ظهور خمول أو إسهال أو نفوق، اعزل الحيوان واطلب تشخيصاً بيطرياً، ولا تخلط أعماراً ومجموعات مختلفة دون تنظيم."]]},fr:{title:"Aménager un élevage de lapins : ventilation, chaleur et hygiène",excerpt:"Température, ventilation et sol propre influencent la santé et la productivité des lapins.",body:[["Local et cages","Installez les cages dans un endroit calme, ventilé et protégé du soleil direct et des courants d’air forts. Gardez les surfaces sèches et faciles à nettoyer, avec un espace adapté et des sols qui protègent les pattes."],["Hygiène et observation","Nettoyez régulièrement mangeoires et abreuvoirs et éliminez humidité et déjections. Observez chaque jour appétit, fèces et respiration. En cas d’abattement, diarrhée ou mortalité, isolez l’animal et demandez un diagnostic vétérinaire."]]},en:{title:"Setting up rabbit housing: ventilation, heat and hygiene",excerpt:"Temperature, ventilation and clean flooring strongly affect rabbit health and performance.",body:[["Location and cages","Place cages in a quiet, well-ventilated area protected from direct sun and strong draughts. Keep surfaces dry and easy to clean, provide adequate movement space and protect feet from harmful flooring."],["Hygiene and observation","Clean feeders and drinkers regularly and remove damp bedding and waste. Check appetite, droppings and breathing daily. Isolate animals showing lethargy, diarrhoea or illness and seek veterinary diagnosis."]]}},
{ id:"rabbit-breeding",cat:"small",mins:6,src:[["FAO – The rabbit: husbandry, health and production","https://www.fao.org/4/x5082e/x5082e00.htm"]],ar:{title:"تكاثر الأرانب ورعاية الأمهات والصغار",excerpt:"سجلات التلقيح والولادة وفحص العش تساعد على تحسين إدارة قطيع الأرانب.",body:[["إدارة التزاوج","اختر أمهات وفحولاً سليمة ومن مصادر موثوقة، وتجنب التزاوج بين الأقارب قدر الإمكان. سجّل تاريخ التلقيح والولادة وعدد الخلفة والفطام، وراقب حالة الأم قبل وبعد الولادة."],["العش والفطام","جهّز صندوق عش نظيفاً وجافاً في الوقت المناسب، وافحص الصغار بلطف للتأكد من دفئهم وسلامتهم. حافظ على الهدوء والماء والعلف للأم. حدّد موعد الفطام وفق العمر والحالة والإرشاد الفني المحلي، ولا تفطم الصغار الضعيفة مبكراً."]]},fr:{title:"Reproduction du lapin et soins aux mères et aux lapereaux",excerpt:"Les registres de saillie, mise bas et contrôle du nid améliorent la conduite de l’élevage.",body:[["Gestion de la reproduction","Choisissez des reproducteurs sains et de provenance fiable ; évitez autant que possible la consanguinité. Notez saillie, mise bas, taille de portée et sevrage. Surveillez l’état de la femelle avant et après la mise bas."],["Nid et sevrage","Préparez un nid propre et sec au bon moment et vérifiez délicatement chaleur et état des petits. Gardez eau et aliment disponibles pour la mère. Décidez du sevrage selon âge, état et conseil technique local ; ne sevrez pas trop tôt les petits faibles."]]},en:{title:"Rabbit reproduction and care of does and kits",excerpt:"Mating, kindling and nest records help improve rabbit herd management.",body:[["Breeding management","Choose healthy breeding animals from reliable sources and avoid close inbreeding where possible. Record mating, kindling, litter size and weaning. Monitor the doe before and after kindling."],["Nest and weaning","Prepare a clean, dry nest box at the appropriate time and gently check that kits are warm and safe. Keep feed and water available to the doe. Set weaning based on age, condition and local technical advice; do not wean weak kits too early."]]}},
{ id:"layers",cat:"birds",mins:7,src:[["FAO – Poultry development","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"تربية الدجاج البياض وإدارة إنتاج البيض",excerpt:"الإضاءة والماء والعلف وجمع البيض والنظافة تؤثر في الإنتاج وجودته.",body:[["تهيئة القطيع","اشترِ بداري من مصدر معروف وسجلات صحية واضحة. جهّز حظيرة جافة جيدة التهوية، وأعشاشاً نظيفة ومجاثم مناسبة، مع حماية من القوارض والطيور البرية."],["الإنتاج والجودة","وفّر علفاً متوازناً وماءً دائماً، واجمع البيض بانتظام ونظّف الأعشاش. سجّل عدد البيض والبيض المكسور واستهلاك العلف والنفوق. أي تغيير مفاجئ في الإنتاج أو القشرة أو الشهية يستدعي مراجعة الإدارة والاتصال بالبيطري عند الاشتباه بمرض."]]},fr:{title:"Poules pondeuses : conduite et production des œufs",excerpt:"Lumière, eau, alimentation, collecte et hygiène influencent rendement et qualité.",body:[["Préparer le lot","Achetez des poulettes auprès d’une source connue avec un historique sanitaire. Préparez un bâtiment sec et ventilé, des pondoirs propres et des perchoirs adaptés, en limitant l’accès aux rongeurs et oiseaux sauvages."],["Production et qualité","Fournissez un aliment équilibré et de l’eau en permanence. Ramassez les œufs régulièrement et gardez les nids propres. Notez ponte, œufs cassés, consommation et mortalité. Une baisse soudaine ou des coquilles anormales justifient une vérification et un avis vétérinaire si maladie suspectée."]]},en:{title:"Layer chicken farming and egg production management",excerpt:"Lighting, water, feed, egg collection and hygiene affect laying performance and quality.",body:[["Preparing the flock","Buy pullets from a traceable source with health records. Provide a dry, ventilated house, clean nest boxes and suitable perches, while limiting rodents and wild birds."],["Production and quality","Provide balanced feed and constant clean water. Collect eggs regularly and keep nests clean. Record egg numbers, cracked eggs, feed intake and mortality. Sudden production changes or abnormal shells call for a management review and veterinary advice if disease is suspected."]]}},
{ id:"broilers",cat:"birds",mins:7,src:[["FAO – Poultry development","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"تربية دجاج اللحم: من استقبال الصيصان إلى التسويق",excerpt:"التحضير قبل وصول الصيصان ومراقبة الحرارة والماء والفرشة أساس دورة ناجحة.",body:[["قبل وصول الصيصان","نظّف الحظيرة وطهّرها وفق إرشادات المختص واتركها تجف، وجهّز الفرشة والمشارب والمعالف. تأكد من أن التدفئة والتهوية تعملان وأن الماء متاح قبل الاستقبال."],["أثناء الدورة","راقب توزيع الصيصان وسلوكها واستهلاك الماء والعلف والفرشة. تجنب الازدحام وسوء التهوية والرطوبة. زن عينة بانتظام وسجّل النفوق واستهلاك العلف، وخطط للتسويق والنقل قبل موعد البيع."]]},fr:{title:"Poulet de chair : de l’arrivée des poussins à la vente",excerpt:"Préparation du bâtiment, température, eau et litière sont essentiels au démarrage.",body:[["Avant l’arrivée","Nettoyez et désinfectez le bâtiment selon les conseils techniques, puis laissez sécher. Préparez litière, abreuvoirs et mangeoires. Vérifiez chauffage, ventilation et disponibilité de l’eau avant l’arrivée."],["Pendant le lot","Observez répartition, comportement, consommation d’eau et d’aliment, ainsi que la litière. Évitez surdensité, mauvaise ventilation et humidité. Pesez un échantillon, notez mortalité et consommation, et préparez la vente et le transport à l’avance."]]},en:{title:"Broiler production: from chick arrival to marketing",excerpt:"House preparation and monitoring heat, water and litter are critical for a good start.",body:[["Before chicks arrive","Clean and disinfect the house according to technical guidance, then allow it to dry. Prepare litter, drinkers and feeders. Check heating, ventilation and water before placement."],["During the flock","Observe chick distribution and behaviour, water and feed intake, and litter condition. Avoid overcrowding, poor ventilation and dampness. Weigh a sample regularly, record mortality and feed use, and plan marketing and transport before sale."]]}},
{ id:"turkey",cat:"birds",mins:6,src:[["FAO – Poultry production","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"تربية الديك الرومي: متطلبات الحظيرة والتغذية",excerpt:"الديك الرومي يحتاج إلى متابعة دقيقة في البداية ومساحة وتهوية وماء نظيف.",body:[["الاستقبال والمأوى","جهّز مكاناً جافاً دافئاً للصغار مع تهوية دون تيارات مباشرة، ومشارب يسهل الوصول إليها. راقب تجمع الطيور أو ابتعادها عن مصدر الحرارة؛ فالسلوك يعطي مؤشراً على الراحة."],["النمو والوقاية","قدّم علفاً مخصصاً للمرحلة العمرية وماءً نظيفاً، وحافظ على الفرشة جافة. لا تخلط أعماراً مختلفة دون خطة صحية. استشر الطبيب البيطري حول التحصينات والأمراض الشائعة في منطقتك."]]},fr:{title:"Élevage de dindes : bâtiment et alimentation",excerpt:"Les dindonneaux demandent une surveillance attentive, de l’espace, de l’air et de l’eau propre.",body:[["Accueil et logement","Préparez un espace sec et chaud pour les jeunes, ventilé sans courants d’air directs, avec des abreuvoirs accessibles. Observez les regroupements ou l’éloignement de la source de chaleur."],["Croissance et prévention","Distribuez un aliment adapté à l’âge et de l’eau propre, en maintenant la litière sèche. Ne mélangez pas les âges sans plan sanitaire. Demandez au vétérinaire les vaccinations et risques propres à votre région."]]},en:{title:"Turkey farming: housing and feeding requirements",excerpt:"Young turkeys need close early monitoring, space, ventilation and clean water.",body:[["Brooding and housing","Prepare a warm, dry area for poults with ventilation but no direct draughts and easy-to-reach drinkers. Watch for crowding or avoidance of the heat source as signs of discomfort."],["Growth and prevention","Provide age-appropriate feed and clean water, and keep litter dry. Avoid mixing age groups without a health plan. Ask a veterinarian about vaccination and local disease risks."]]}},
{ id:"geese",cat:"birds",mins:5,src:[["FAO – Poultry production","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"تربية البط والإوز: الماء والمأوى وإدارة القطيع",excerpt:"السباحة ليست بديلاً عن الماء النظيف للشرب والمأوى الجاف والتهوية الجيدة.",body:[["المكان والماء","وفّر ماء شرب نظيفاً دائماً وأحواضاً مناسبة إذا توفرت، مع تصريف يمنع تحول الأرضية إلى طين ورطوبة. جهّز مأوى ليلياً جافاً يحمي الطيور من المفترسات والبرد."],["التغذية والتكاثر","قدّم علفاً متوازناً مناسباً للعمر والإنتاج، ولا تعتمد على بقايا الطعام وحدها. راقب نظافة الماء والريش والأرجل، واجمع البيض وخزّنه بطريقة نظيفة، واعزل الطيور المريضة."]]},fr:{title:"Élever canards et oies : eau, abri et conduite du lot",excerpt:"La baignade ne remplace pas l’eau potable propre, un abri sec et une bonne ventilation.",body:[["Espace et eau","Fournissez toujours de l’eau potable propre et, si possible, un bassin adapté avec drainage pour éviter boue et humidité. Prévoyez un abri nocturne sec contre prédateurs et froid."],["Alimentation et reproduction","Distribuez un aliment équilibré selon l’âge et l’objectif ; les seuls restes de cuisine ne suffisent pas. Surveillez l’eau, le plumage et les pattes, ramassez les œufs proprement et isolez les oiseaux malades."]]},en:{title:"Duck and goose keeping: water, shelter and flock care",excerpt:"Swimming water does not replace clean drinking water, dry shelter and good ventilation.",body:[["Space and water","Provide clean drinking water at all times and suitable bathing access where possible, with drainage to prevent mud and dampness. Provide a dry night shelter against predators and cold."],["Feeding and breeding","Use balanced feed suited to age and production; kitchen scraps alone are not a complete diet. Monitor water, feathers and feet, collect eggs hygienically and separate sick birds."]]}},
{ id:"beekeeping",cat:"bees",mins:7,src:[["FAO – Good beekeeping practices","https://www.fao.org/3/i0842e/i0842e.pdf"]],ar:{title:"مدخل إلى تربية النحل: اختيار الموقع وفحص الخلايا",excerpt:"الموقع الهادئ وتوفر النباتات المزهرة والماء والفحص المنتظم تساعد على استقرار المنحل.",body:[["اختيار الموقع","اختر مكاناً بعيداً عن حركة الناس والرش العشوائي للمبيدات، قريباً من مصادر الرحيق والماء، مع ظل جزئي وحماية من الرياح. اترك مسافات آمنة وممرات للعمل."],["فحص الخلايا","افحص الخلايا في طقس مناسب وبهدوء، وسجّل قوة الطائفة ووجود الملكة والحضنة ومخزون الغذاء وأي علامات غير طبيعية. تعلّم استخدام معدات الوقاية والتعامل الآمن مع النحل، واستعن بمرشد محلي عند ظهور آفات أو ضعف شديد."]]},fr:{title:"Introduction à l’apiculture : emplacement et inspection des ruches",excerpt:"Un site calme, des floraisons, de l’eau et des visites régulières favorisent un rucher stable.",body:[["Choisir le site","Choisissez un lieu éloigné des passages et des pulvérisations non maîtrisées, proche des ressources mellifères et de l’eau, avec ombre partielle et protection contre le vent. Prévoyez des distances de sécurité."],["Inspecter les colonies","Visitez par météo adaptée et avec calme. Notez force de la colonie, présence de la reine, couvain, réserves et signes inhabituels. Apprenez les équipements de protection et demandez conseil en cas de ravageurs ou d’affaiblissement."]]},en:{title:"Beekeeping basics: apiary site and hive inspections",excerpt:"A calm site with flowering forage, water and regular checks supports a healthy apiary.",body:[["Choosing a site","Choose a location away from busy paths and uncontrolled pesticide spraying, near flowering forage and water, with partial shade and wind protection. Maintain safe working distances."],["Hive inspections","Inspect in suitable weather and work calmly. Record colony strength, queen presence, brood, food stores and unusual signs. Learn safe protective equipment and seek local help for pests or severe colony decline."]]}},
{ id:"honey-harvest",cat:"bees",mins:5,src:[["FAO – Good beekeeping practices","https://www.fao.org/3/i0842e/i0842e.pdf"]],ar:{title:"جني العسل وتخزينه مع الحفاظ على الجودة",excerpt:"النظافة ونضج الأقراص والتعبئة الجافة تحمي جودة العسل وتقلل التخمر.",body:[["موعد الجني","لا تجنِ الأقراص غير الناضجة أو التي تحتوي على رحيق غير مختوم بما يكفي. اختر وقتاً مناسباً وقلّل إزعاج الطائفة، ولا تترك الخلايا دون مخزون غذائي كافٍ."],["الاستخلاص والتخزين","استخدم أدوات نظيفة وجافة ومخصصة للغذاء، وصفِّ العسل وخزّنه في أوعية غذائية محكمة بعيداً عن الرطوبة والحرارة والروائح. ضع بطاقة بتاريخ الجني والمنطقة، واتبع متطلبات السلامة والتوسيم المحلية."]]},fr:{title:"Récolter et conserver le miel en préservant sa qualité",excerpt:"Hygiène, maturité des opercules et conditionnement sec limitent la fermentation.",body:[["Moment de récolte","Ne récoltez pas les cadres insuffisamment mûrs ou contenant trop de nectar non operculé. Choisissez un moment adapté et limitez la perturbation de la colonie sans la priver de réserves."],["Extraction et stockage","Utilisez du matériel propre, sec et apte au contact alimentaire. Filtrez et stockez dans des contenants alimentaires hermétiques, à l’abri de l’humidité, chaleur et odeurs. Indiquez date et origine et respectez les règles locales d’étiquetage."]]},en:{title:"Harvesting and storing honey while protecting quality",excerpt:"Hygiene, capped-comb maturity and dry packaging help prevent fermentation.",body:[["Harvest timing","Avoid harvesting immature frames or combs with excessive uncapped nectar. Choose suitable conditions and minimize colony disturbance without removing essential food stores."],["Extraction and storage","Use clean, dry, food-grade equipment. Filter and store honey in sealed food containers away from moisture, heat and strong odours. Label harvest date and origin and follow local food-safety and labelling rules."]]}},
{ id:"fish-pond",cat:"fish",mins:7,src:[["FAO – Small-scale aquaculture","https://www.fao.org/fishery/en/topic/166235"]],ar:{title:"مدخل إلى تربية الأسماك في الأحواض",excerpt:"اختيار مصدر الماء وتصميم الحوض وكثافة التخزين يجب أن تسبق شراء الإصبعيات.",body:[["قبل إنشاء الحوض","تحقق من مصدر الماء واستمراريته وجودته وإمكانية تصريفه، وادرس التربة والتسرب والتراخيص المحلية. لا تملأ الحوض بكثافة عالية دون تصميم وخطة تشغيل."],["التغذية والمتابعة","اشترِ إصبعيات سليمة من مصدر موثوق، وقدّم علفاً مخصصاً للنوع والحجم. راقب سلوك الأسماك واستهلاك العلف ونفوقها وجودة الماء، وضع خطة للطوارئ عند انقطاع الكهرباء أو التهوية."]]},fr:{title:"Introduction à l’élevage de poissons en étang",excerpt:"Source d’eau, conception du bassin et densité de stockage doivent être étudiées avant l’achat des alevins.",body:[["Avant de construire","Vérifiez disponibilité, qualité et évacuation de l’eau, nature du sol, risques de fuite et autorisations locales. Ne stockez pas à forte densité sans conception ni plan d’exploitation."],["Alimentation et suivi","Achetez des alevins sains auprès d’une source fiable et utilisez un aliment adapté à l’espèce et à la taille. Surveillez comportement, consommation, mortalité et qualité de l’eau. Prévoyez une solution de secours pour l’électricité et l’aération."]]},en:{title:"Introduction to fish farming in ponds",excerpt:"Water source, pond design and stocking density must be assessed before buying fingerlings.",body:[["Before building a pond","Check water availability, quality and drainage, soil suitability, leakage risk and local permits. Do not stock at high density without a design and operating plan."],["Feeding and monitoring","Buy healthy fingerlings from a reliable source and use feed suited to species and size. Monitor fish behaviour, feed intake, mortality and water quality. Plan backup arrangements for power and aeration failures."]]}},
{ id:"fish-water",cat:"fish",mins:6,src:[["FAO – Aquaculture","https://www.fao.org/fishery/en/topic/166235"]],ar:{title:"جودة الماء في تربية الأسماك: ما الذي يجب مراقبته؟",excerpt:"الأكسجين والحرارة ودرجة الحموضة والأمونيا مؤشرات مهمة، ولا يكفي صفاء الماء وحده.",body:[["مؤشرات الماء","راقب درجة الحرارة والأكسجين المذاب ودرجة الحموضة والأمونيا والنتريت بأدوات مناسبة. تختلف الحدود المقبولة حسب النوع ومرحلة النمو؛ استخدم إرشادات فنية خاصة بالنوع."],["علامات الإنذار","تجمع الأسماك عند السطح أو قرب دخول الماء، أو توقفها عن الأكل أو زيادة النفوق، علامات تستدعي فحص الماء فوراً. لا تضف مواد كيميائية عشوائياً؛ أوقف التغذية مؤقتاً عند الاشتباه بمشكلة واطلب مساعدة مختص."]]},fr:{title:"Qualité de l’eau en pisciculture : paramètres à surveiller",excerpt:"Oxygène, température, pH et ammoniaque sont essentiels ; l’eau claire ne suffit pas.",body:[["Paramètres de l’eau","Suivez température, oxygène dissous, pH, ammoniac et nitrites avec des instruments adaptés. Les plages acceptables varient selon l’espèce et le stade ; utilisez des références techniques spécifiques."],["Signes d’alerte","Des poissons en surface, près de l’arrivée d’eau, qui cessent de s’alimenter ou meurent davantage exigent un contrôle immédiat. N’ajoutez pas de produits chimiques au hasard ; suspendez prudemment l’alimentation si nécessaire et demandez conseil."]]},en:{title:"Water quality in fish farming: what should be monitored?",excerpt:"Oxygen, temperature, pH and ammonia matter; clear-looking water alone is not enough.",body:[["Water parameters","Monitor temperature, dissolved oxygen, pH, ammonia and nitrite with suitable test equipment. Acceptable ranges vary by species and life stage, so use species-specific technical guidance."],["Warning signs","Fish piping at the surface, crowding near inflows, refusing feed or increased mortality require prompt water checks. Do not add chemicals at random; seek expert help and manage feeding carefully while investigating."]]}},
{ id:"soil-test",cat:"crops",mins:6,src:[["FAO – Soils portal","https://www.fao.org/soils-portal/en/"]],ar:{title:"تحليل التربة قبل الزراعة: لماذا وكيف؟",excerpt:"تحليل عينة ممثلة يوفر أساساً أفضل لاختيار التسميد وتصحيح مشاكل الملوحة والحموضة.",body:[["أخذ العينة","قسّم الحقل إلى مناطق متجانسة حسب اللون والانحدار والمحصول السابق. خذ عينات فرعية من عمق مناسب للمحصول، وامزجها في عينة مركبة نظيفة، مع تجنب أماكن السماد المتجمع والحواف."],["قراءة النتائج","اطلب تحاليل تناسب حاجتك مثل pH والملوحة والمادة العضوية والعناصر الغذائية. لا تضف الجير أو الجبس أو السماد اعتماداً على التخمين؛ اربط النتائج بالمحصول ومياه الري واستشر مختصاً محلياً."]]},fr:{title:"Analyser le sol avant de planter : pourquoi et comment ?",excerpt:"Un échantillon représentatif aide à choisir la fertilisation et à diagnostiquer salinité ou acidité.",body:[["Prélever un échantillon","Divisez la parcelle en zones homogènes selon couleur, pente et précédent cultural. Prélevez plusieurs sous-échantillons à la profondeur adaptée, mélangez-les dans un récipient propre et évitez tas d’engrais et bordures."],["Interpréter les résultats","Demandez les analyses utiles : pH, salinité, matière organique et éléments nutritifs. N’appliquez pas chaux, gypse ou engrais au hasard ; interprétez les résultats selon la culture et l’eau d’irrigation avec un conseiller local."]]},en:{title:"Soil testing before planting: why and how",excerpt:"A representative soil sample provides a better basis for fertilizer choices and salinity or acidity management.",body:[["Taking a sample","Divide the field into uniform zones by colour, slope and previous crop. Take several subsamples at a crop-appropriate depth, mix in a clean container and avoid fertilizer heaps and field edges."],["Reading results","Request relevant tests such as pH, salinity, organic matter and nutrients. Do not apply lime, gypsum or fertilizer by guesswork; interpret results for the crop and irrigation water with local technical advice."]]}},
{ id:"compost",cat:"crops",mins:6,src:[["FAO – Soil management","https://www.fao.org/soils-portal/soil-management/en/"]],ar:{title:"تحضير السماد العضوي واستخدامه بأمان",excerpt:"الكمبوست الناضج يحسن المادة العضوية وبنية التربة عند تحضيره وإضافته بشكل صحيح.",body:[["المواد والتحضير","اخلط مواد نباتية جافة مع مواد خضراء رطبة وروث مناسب بنسب تسمح بالتهوية والرطوبة. قلّب الكومة وتابع حرارتها ورطوبتها، وامنع دخول البلاستيك والزيوت والمواد الملوثة."],["علامات النضج والاستخدام","يكون السماد الناضج أقرب إلى لون داكن ورائحة ترابية وقوام متجانس، دون سخونة واضحة أو بقايا طازجة كثيرة. لا تستخدم روثاً طازجاً مباشرة قرب المحاصيل الغذائية؛ اتبع فترات التحلل والسلامة المحلية."]]},fr:{title:"Préparer et utiliser le compost en toute sécurité",excerpt:"Un compost mûr améliore matière organique et structure du sol lorsqu’il est bien préparé.",body:[["Matières et préparation","Mélangez matières végétales sèches et matières vertes humides avec du fumier adapté, en maintenant air et humidité. Retournez le tas et suivez température et humidité. Écartez plastiques, huiles et déchets contaminés."],["Maturité et utilisation","Un compost mûr est plutôt sombre, homogène et sent la terre, sans chaleur marquée ni nombreux résidus frais. N’épandez pas du fumier frais directement près des cultures alimentaires ; respectez les délais de compostage et règles sanitaires."]]},en:{title:"Making and safely using organic compost",excerpt:"Mature compost can improve soil organic matter and structure when properly prepared.",body:[["Materials and preparation","Mix dry plant material with moist green material and suitable manure while maintaining airflow and moisture. Turn the pile and monitor temperature and moisture. Keep out plastics, oils and contaminated waste."],["Maturity and use","Mature compost is generally dark, crumbly and earthy-smelling, without notable heat or many fresh residues. Do not apply fresh manure directly near food crops; follow safe composting periods and local guidance."]]}},
{ id:"fertilizer",cat:"crops",mins:7,src:[["FAO – Plant nutrition for food security","https://www.fao.org/4/a0443e/a0443e00.htm"]],ar:{title:"التسميد المتوازن: كيف تتجنب الإسراف ونقص العناصر؟",excerpt:"الجرعة الصحيحة تعتمد على تحليل التربة والمحصول ومرحلة النمو ومياه الري.",body:[["خطة التسميد","ابدأ بتحليل التربة ومراجعة المحصول السابق والهدف الإنتاجي. قسّم الاحتياجات بين العناصر الكبرى والصغرى، ولا تخلط الأسمدة دون التأكد من توافقها وتعليمات الملصق."],["التوقيت والسلامة","وزّع الإضافات على مراحل تناسب امتصاص النبات، وتجنب ملامسة السماد المركز للبذور والجذور. خزّن الأسمدة في مكان جاف وآمن بعيداً عن الأطفال والأعلاف والمياه، وسجّل الكميات والتواريخ."]]},fr:{title:"Fertilisation équilibrée : éviter excès et carences",excerpt:"La dose dépend de l’analyse du sol, de la culture, du stade et de l’eau d’irrigation.",body:[["Plan de fertilisation","Commencez par une analyse du sol et l’historique cultural. Répartissez les besoins entre éléments majeurs et oligoéléments. Ne mélangez pas les engrais sans vérifier leur compatibilité et l’étiquette."],["Calendrier et sécurité","Fractionnez les apports selon l’absorption de la plante et évitez le contact d’engrais concentrés avec graines et racines. Stockez au sec, en sécurité, loin des enfants, aliments et eaux. Notez doses et dates."]]},en:{title:"Balanced fertilization: avoiding waste and nutrient deficiency",excerpt:"Rates depend on soil tests, crop, growth stage and irrigation water.",body:[["Fertilizer plan","Start with soil analysis and cropping history. Match major and micronutrient needs to the crop. Do not mix fertilizers without checking compatibility and label instructions."],["Timing and safety","Split applications to match crop uptake and keep concentrated fertilizer away from seeds and roots. Store products securely and dry, away from children, feed and water. Record rates and dates."]]}},
{ id:"tomato",cat:"crops",mins:7,src:[["FAO – Good agricultural practices","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"زراعة الطماطم في البيوت البلاستيكية",excerpt:"اختيار الشتلات والتهوية والري المنتظم والتقليم والنظافة تساعد على إنتاج أفضل.",body:[["قبل الغرس","اختر شتلات سليمة وصنفاً مناسباً للموسم والسوق. جهّز التربة وحلّلها، ونظّف البيت البلاستيكي وتأكد من التهوية والصرف وشبكة الري."],["أثناء النمو","راقب الرطوبة دون إغراق، واربط النباتات ووجّهها وفق نظام التربية، وأزل الأوراق المصابة بأدوات نظيفة. افحص أسفل الأوراق بانتظام لاكتشاف الحشرات والأعراض مبكراً، وطبّق المكافحة المتكاملة بدل الرش العشوائي."]]},fr:{title:"Culture de la tomate sous serre",excerpt:"Plants sains, ventilation, irrigation régulière, taille et hygiène favorisent la production.",body:[["Avant plantation","Choisissez des plants sains et une variété adaptée à la saison et au marché. Analysez et préparez le sol, nettoyez la serre et vérifiez ventilation, drainage et irrigation."],["Pendant la culture","Maintenez une humidité régulière sans excès. Tuteurez et conduisez les plants selon le système choisi ; retirez les feuilles malades avec des outils propres. Inspectez le dessous des feuilles et privilégiez la lutte intégrée plutôt que les traitements systématiques."]]},en:{title:"Growing greenhouse tomatoes",excerpt:"Healthy transplants, ventilation, steady irrigation, pruning and sanitation support production.",body:[["Before planting","Choose healthy transplants and a variety suited to the season and market. Test and prepare soil, clean the greenhouse and check ventilation, drainage and irrigation."],["During growth","Maintain steady moisture without waterlogging. Train and support plants using the chosen system, and remove diseased leaves with clean tools. Inspect leaf undersides regularly and use integrated pest management rather than routine spraying."]]}},
{ id:"potato",cat:"crops",mins:6,src:[["FAO – Plant production and protection","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"زراعة البطاطا: التقاوي والري والترديم والحصاد",excerpt:"التقاوي السليمة والدورة الزراعية والري المتوازن تحد من مشاكل المحصول.",body:[["اختيار التقاوي والأرض","استعمل تقاوي معتمدة أو موثوقة وخالية من التعفن، واختر أرضاً جيدة الصرف. تجنب تكرار البطاطا في نفس القطعة باستمرار، وراعِ تاريخ الزراعة المناسب لمنطقتك."],["العناية والحصاد","حافظ على رطوبة متوازنة وتجنب التغريق، ونفّذ الترديم لحماية الدرنات من الضوء. راقب الآفات والأمراض، وأوقف الري قبل الحصاد وفق نوع التربة والطقس، ثم جفف الدرنات وظللها وخزنها في مكان مناسب."]]},fr:{title:"Culture de la pomme de terre : plants, irrigation et récolte",excerpt:"Plants sains, rotation et irrigation équilibrée réduisent les problèmes de culture.",body:[["Plants et parcelle","Utilisez des plants certifiés ou fiables, sans pourriture, et choisissez un sol bien drainé. Évitez de cultiver la pomme de terre continuellement sur la même parcelle et respectez le calendrier local."],["Entretien et récolte","Maintenez une humidité régulière sans saturation et buttez pour protéger les tubercules de la lumière. Surveillez ravageurs et maladies. Ajustez l’arrêt de l’irrigation au sol et à la météo, puis séchez et stockez les tubercules à l’abri."]]},en:{title:"Potato growing: seed tubers, irrigation, earthing-up and harvest",excerpt:"Healthy seed tubers, crop rotation and balanced irrigation help prevent crop problems.",body:[["Seed and field choice","Use certified or reliable disease-free seed tubers and well-drained soil. Avoid continuous potato cropping on the same field and follow the locally suitable planting window."],["Crop care and harvest","Maintain even moisture without waterlogging and earth up to protect tubers from light. Monitor pests and disease. Time irrigation shutoff to soil and weather, then cure and store tubers in suitable shaded conditions."]]}},
{ id:"olive",cat:"crops",mins:7,src:[["International Olive Council – Olive growing","https://www.internationaloliveoil.org/"]],ar:{title:"العناية بأشجار الزيتون: التقليم والري والتغذية",excerpt:"التقليم المتوازن ومراقبة الرطوبة والتغذية حسب التحليل تدعم نمو الشجرة والإنتاج.",body:[["التقليم","أزل الأغصان الميتة والمتقاطعة والمتزاحمة مع الحفاظ على هيكل متوازن يسمح بدخول الضوء والهواء. تجنب التقليم الجائر غير الضروري، ونظّف الأدوات بين الأشجار عند وجود أعراض مرضية."],["الماء والتغذية","تختلف حاجة الزيتون للماء حسب عمر الشجرة والتربة والمناخ والحمل. راقب رطوبة منطقة الجذور، ولا تفرط في الري. اعتمد تحليل التربة أو الأوراق لتحديد التسميد، وسجّل الإنتاج وتناوب الحمل."]]},fr:{title:"Entretien de l’olivier : taille, irrigation et nutrition",excerpt:"Une taille équilibrée et une gestion de l’eau et des nutriments fondée sur l’observation soutiennent l’arbre.",body:[["Taille","Supprimez bois mort, branches croisées et zones trop denses en conservant une charpente équilibrée laissant entrer lumière et air. Évitez les tailles sévères inutiles et nettoyez les outils si des symptômes sont présents."],["Eau et nutrition","Les besoins en eau varient selon âge, sol, climat et charge en fruits. Suivez l’humidité racinaire sans excès d’irrigation. Utilisez analyses de sol ou de feuilles pour raisonner la fertilisation et notez rendement et alternance."]]},en:{title:"Olive tree care: pruning, irrigation and nutrition",excerpt:"Balanced pruning and observation-led water and nutrient management support tree health and yield.",body:[["Pruning","Remove dead, crossing and overcrowded branches while keeping a balanced structure that allows light and airflow. Avoid unnecessary severe pruning and clean tools where disease symptoms occur."],["Water and nutrition","Water needs vary with tree age, soil, climate and crop load. Monitor root-zone moisture and avoid over-irrigation. Use soil or leaf analysis to guide fertilizer and record yield and alternate bearing."]]}},
{ id:"dates",cat:"crops",mins:7,src:[["FAO – Date palm cultivation","https://www.fao.org/land-water/databases-and-software/crop-information/date-palm/en/"]],ar:{title:"خدمة النخيل: التلقيح والخف والعناية بالثمار",excerpt:"التلقيح المنظم والخف والنظافة ومراقبة السوسة الحمراء عناصر مهمة في بساتين النخيل.",body:[["التلقيح والخف","تختلف مواعيد التلقيح حسب الصنف والمنطقة والطقس. استخدم حبوب لقاح سليمة وممارسات نظيفة، وسجّل مصدر اللقاح وتاريخه. يضبط الخف عدد العذوق والشماريخ بما يناسب قوة النخلة والهدف التسويقي."],["الصحة والخدمة","راقب قواعد السعف والجذع وأعراض الثقوب أو الإفرازات أو الذبول، وبلّغ المختص عند الاشتباه بآفة خطيرة مثل سوسة النخيل الحمراء. لا تترك مخلفات التقليم المصابة قرب البستان، ونظّف الأدوات واتبع الإرشادات الرسمية المحلية."]]},fr:{title:"Conduite du palmier dattier : pollinisation et éclaircissage",excerpt:"Pollinisation organisée, éclaircissage, hygiène et surveillance des ravageurs sont essentiels.",body:[["Pollinisation et éclaircissage","Les dates varient selon variété, région et météo. Utilisez du pollen sain et des pratiques propres ; notez sa provenance et la date. L’éclaircissage ajuste le nombre de régimes et de brins à la vigueur du palmier et au marché."],["Santé et entretien","Surveillez bases des palmes et tronc : trous, écoulements ou dépérissement peuvent signaler un problème grave. En cas de suspicion de charançon rouge, contactez rapidement les services compétents. Évacuez les déchets infestés et nettoyez les outils."]]},en:{title:"Date palm management: pollination, thinning and fruit care",excerpt:"Organized pollination, thinning, sanitation and pest monitoring are important in date orchards.",body:[["Pollination and thinning","Timing varies with cultivar, region and weather. Use healthy pollen and clean practices, recording its source and date. Thinning adjusts bunch and strand load to palm vigour and market goals."],["Health and maintenance","Inspect leaf bases and trunks for holes, oozing or decline. Report suspected serious pests such as red palm weevil promptly to local authorities. Remove infested pruning waste and clean tools according to local guidance."]]}},
{ id:"cereals",cat:"crops",mins:6,src:[["FAO – Conservation agriculture","https://www.fao.org/conservation-agriculture/en/"]],ar:{title:"زراعة الحبوب في الجزائر: التحضير والبذر والمتابعة",excerpt:"موعد البذر وكثافة البذور والرطوبة والدورة الزراعية تتغير حسب المنطقة والمطر.",body:[["تحضير الأرض والبذر","حلّل التربة واختر بذوراً موثوقة وصنفاً ملائماً للمنطقة. اضبط موعد البذر وعمقه والكثافة وفق التوصيات المحلية ونوع التربة والرطوبة، ولا تبذر في أرض شديدة الجفاف أو مشبعة بالماء."],["متابعة الموسم","راقب الإنبات والأعشاب والأمراض والحشرات، واستعمل الدورة الزراعية وإدارة بقايا المحصول. قرر التسميد حسب تحليل التربة وتوقعات المطر ومرحلة النمو، وسجّل المدخلات والمحصول النهائي."]]},fr:{title:"Céréales en Algérie : préparation, semis et suivi",excerpt:"Date de semis, densité, humidité et rotation varient selon la région et la pluviométrie.",body:[["Préparer et semer","Analysez le sol, choisissez des semences fiables et une variété adaptée. Réglez date, profondeur et densité selon recommandations locales, sol et humidité. Évitez de semer dans un sol trop sec ou saturé."],["Suivi de campagne","Surveillez levée, adventices, maladies et insectes. Utilisez rotation et gestion des résidus. Raisonnez la fertilisation selon analyse, pluies attendues et stade, puis consignez intrants et rendement."]]},en:{title:"Cereal production in Algeria: preparation, sowing and monitoring",excerpt:"Sowing date, seed rate, moisture and rotation vary with region and rainfall.",body:[["Field preparation and sowing","Test soil, choose reliable seed and a locally adapted variety. Set sowing date, depth and rate using local recommendations, soil type and moisture. Avoid sowing into extremely dry or waterlogged soil."],["Season monitoring","Monitor emergence, weeds, diseases and insects. Use crop rotation and residue management. Base fertilizer decisions on soil tests, expected rainfall and growth stage, and record inputs and final yield."]]}},
{ id:"ipm",cat:"crops",mins:7,src:[["FAO – Integrated pest management","https://www.fao.org/pest-and-pesticide-management/ipm/integrated-pest-management/en/"]],ar:{title:"المكافحة المتكاملة للآفات: قلّل الرش وارفع فعاليته",excerpt:"التشخيص والمراقبة والوقاية والوسائل الحيوية تسبق قرار استخدام المبيد.",body:[["التعرف والمراقبة","افحص النبات بانتظام وحدد الآفة أو المرض بدقة، وسجّل نسبة الإصابة وتطورها. قد تتشابه أعراض نقص العناصر والمرض والحشرات؛ لا ترش قبل معرفة السبب."],["اختيار وسيلة المكافحة","ابدأ بالنظافة الزراعية والدورة الزراعية والأصناف المقاومة والمصائد والوسائل الحيوية عند توفرها. إذا لزم المبيد، استخدم منتجاً مسجلاً للمحصول والآفة واتبع الملصق وفترة ما قبل الحصاد ومعدات الوقاية، ولا تخلط المنتجات عشوائياً."]]},fr:{title:"Lutte intégrée : réduire les traitements et mieux les cibler",excerpt:"Diagnostic, surveillance, prévention et solutions biologiques précèdent le recours aux pesticides.",body:[["Identifier et surveiller","Inspectez régulièrement les plantes, identifiez précisément ravageur ou maladie et notez le niveau d’attaque. Carences, maladies et insectes peuvent produire des symptômes proches ; ne traitez pas sans diagnostic."],["Choisir une méthode","Commencez par hygiène culturale, rotation, variétés résistantes, pièges et moyens biologiques disponibles. Si un pesticide est nécessaire, utilisez un produit homologué pour la culture et la cible, respectez étiquette, délai avant récolte et protections. Ne mélangez pas au hasard."]]},en:{title:"Integrated pest management: spray less and target better",excerpt:"Diagnosis, monitoring, prevention and biological options should come before pesticide use.",body:[["Identify and monitor","Inspect plants regularly, identify the pest or disease accurately and record severity. Nutrient deficiencies, diseases and insects can look similar; do not spray before diagnosing."],["Choose control methods","Start with sanitation, rotation, resistant varieties, traps and available biological controls. If a pesticide is necessary, use one registered for the crop and target, follow the label, pre-harvest interval and protective equipment. Never mix products randomly."]]}},
{ id:"irrigation-scheduling",cat:"crops",mins:6,src:[["FAO – Water management","https://www.fao.org/land-water/en/"]],ar:{title:"جدولة الري: متى وكم نروي؟",excerpt:"نوع التربة وعمق الجذور والطقس ومرحلة المحصول تحدد توقيت الري وكميته.",body:[["افهم التربة والمحصول","التربة الرملية تفقد الماء أسرع من الطينية، كما تختلف الجذور واحتياجات الماء بين الخضروات والأشجار والحبوب. افحص رطوبة منطقة الجذور ولا تعتمد على سطح التربة وحده."],["راقب النظام","افحص التسرب والضغط والمرشحات ونقاط الانسداد، وسجّل مدة الري وكميته. تجنب الري وقت الرياح القوية أو الحرارة الشديدة قدر الإمكان، ولا تترك النباتات في تشبع مستمر يسبب اختناق الجذور."]]},fr:{title:"Programmer l’irrigation : quand et combien arroser ?",excerpt:"Sol, profondeur racinaire, météo et stade cultural déterminent le moment et la quantité.",body:[["Comprendre sol et culture","Un sol sableux perd l’eau plus vite qu’un sol argileux. Les racines et besoins diffèrent entre légumes, arbres et céréales. Vérifiez l’humidité de la zone racinaire, pas seulement la surface."],["Surveiller le réseau","Contrôlez fuites, pression, filtres et goutteurs bouchés, et notez durée et volume d’irrigation. Évitez autant que possible vent fort et chaleur extrême. Ne maintenez pas le sol saturé, ce qui asphyxie les racines."]]},en:{title:"Irrigation scheduling: when and how much to water",excerpt:"Soil, rooting depth, weather and crop stage determine irrigation timing and amount.",body:[["Understand soil and crop","Sandy soil loses water faster than clay, and rooting depth and needs differ among vegetables, trees and cereals. Check moisture in the root zone, not only at the surface."],["Monitor the system","Check leaks, pressure, filters and blocked emitters, and record irrigation time and volume. Avoid strong winds and extreme heat where possible. Do not keep soil saturated, as roots can suffer from oxygen shortage."]]}},
{ id:"fruit-trees",cat:"crops",mins:6,src:[["FAO – Fruit tree production","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"غرس الأشجار المثمرة: اختيار الشتلة والمسافة والخدمة",excerpt:"الصنف والأصل ومصدر الشتلة والتربة والتلقيح عوامل تحدد نجاح البستان.",body:[["قبل الغرس","اختر صنفاً وأصلاً يناسبان المناخ والتربة والسوق، واشترِ شتلات سليمة من مشتل موثوق. خطط للمسافات وفق قوة النمو ونظام الخدمة، وافحص الصرف ومصدر الماء."],["بعد الغرس","اسقِ لتثبيت التربة حول الجذور دون إغراق، وضع دعامة عند الحاجة واحمِ الجذع من الضرر. راقب الأعشاب والآفات، وتعلم احتياجات التقليم والتلقيح لكل نوع؛ لا تطبق برنامجاً واحداً على كل الأشجار."]]},fr:{title:"Planter des arbres fruitiers : plants, distances et entretien",excerpt:"Variété, porte-greffe, provenance du plant, sol et pollinisation conditionnent le verger.",body:[["Avant plantation","Choisissez variété et porte-greffe adaptés au climat, sol et marché. Achetez des plants sains en pépinière fiable. Définissez les distances selon vigueur et conduite, et vérifiez drainage et ressource en eau."],["Après plantation","Arrosez pour mettre la terre en contact avec les racines sans engorgement. Tuteurez si nécessaire et protégez le tronc. Surveillez adventices et ravageurs ; adaptez taille et pollinisation à chaque espèce."]]},en:{title:"Planting fruit trees: nursery stock, spacing and care",excerpt:"Cultivar, rootstock, plant source, soil and pollination all influence orchard success.",body:[["Before planting","Choose cultivars and rootstocks suited to climate, soil and market. Buy healthy plants from a reputable nursery. Plan spacing for tree vigour and management system, and check drainage and water supply."],["After planting","Water to settle soil around roots without waterlogging. Stake if needed and protect trunks. Monitor weeds and pests; learn pruning and pollination needs for each species rather than using one schedule for all trees."]]}},
{ id:"greenhouse",cat:"crops",mins:6,src:[["FAO – Protected cultivation","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"إدارة البيوت البلاستيكية: الحرارة والرطوبة والتهوية",excerpt:"التحكم في المناخ الداخلي والوقاية والنظافة يحمي المحصول من الإجهاد والأمراض.",body:[["المناخ الداخلي","راقب الحرارة والرطوبة والتهوية يومياً، وافتح الجوانب أو النوافذ وفق الطقس والمحصول. تجنب التكاثف الطويل على الأوراق لأنه يساعد بعض الأمراض، ولا تجعل البيت مغلقاً تماماً في الحر."],["النظافة والدورة","أزل بقايا المحصول والأعشاب، ونظف الأدوات والخزانات وخطوط الري. بدّل المحاصيل أو استخدم أصنافاً مقاومة حيث أمكن، وافحص الشتلات قبل إدخالها حتى لا تنقل الآفات إلى البيت."]]},fr:{title:"Gestion des serres : température, humidité et ventilation",excerpt:"Le contrôle du climat intérieur, la prévention et l’hygiène limitent stress et maladies.",body:[["Climat intérieur","Suivez chaque jour température, humidité et ventilation. Ouvrez les côtés ou ouvrants selon météo et culture. Évitez la condensation prolongée sur les feuilles et ne laissez pas la serre totalement fermée par forte chaleur."],["Hygiène et rotation","Retirez résidus et mauvaises herbes ; nettoyez outils, réservoirs et lignes d’irrigation. Alternez les cultures ou utilisez des variétés résistantes lorsque possible. Inspectez les plants avant leur entrée en serre."]]},en:{title:"Greenhouse management: temperature, humidity and ventilation",excerpt:"Managing the indoor climate, prevention and sanitation reduces crop stress and disease.",body:[["Indoor climate","Monitor temperature, humidity and ventilation daily. Open sides or vents according to weather and crop needs. Avoid prolonged condensation on leaves and do not leave the greenhouse fully closed in hot weather."],["Sanitation and rotation","Remove crop residues and weeds; clean tools, tanks and irrigation lines. Rotate crops or use resistant varieties where possible. Inspect transplants before bringing them into the greenhouse."]]}},
{ id:"farm-records",cat:"sheep",mins:5,src:[["FAO – Farm management","https://www.fao.org/family-farming/detail/en/c/1617774/"]],ar:{title:"دفتر المربي: سجّل الولادات والعلف والمصاريف",excerpt:"السجلات البسيطة تكشف تكلفة الإنتاج والمشاكل المتكررة وتساعد على اتخاذ القرار.",body:[["ماذا تسجل؟","دوّن هوية الحيوان أو المجموعة، الشراء والبيع، التلقيح والولادة، الأوزان، العلف، الأدوية، اللقاحات، النفوق والإنتاج. سجّل التاريخ والكمية والسعر واحتفظ بالفواتير."],["كيف تستفيد؟","احسب تكلفة العلف لكل رأس أو لكل كيلوغرام نمو، ونسبة الولادات والنفوق والإنتاج. راجع الأرقام شهرياً وقارن المواسم، ولا تخلط المصاريف الشخصية بمصاريف المشروع."]]},fr:{title:"Carnet d’éleveur : naissances, alimentation et dépenses",excerpt:"Des registres simples révèlent le coût de production et les problèmes récurrents.",body:[["Que noter ?","Consignez identité de l’animal ou du lot, achats et ventes, saillies, mises bas, poids, aliments, médicaments, vaccins, mortalité et production. Notez date, quantité et prix et gardez les factures."],["Comment l’utiliser ?","Calculez coût alimentaire par tête ou par kilo de croissance, taux de mise bas, mortalité et production. Analysez les chiffres chaque mois et comparez les saisons. Séparez dépenses personnelles et professionnelles."]]},en:{title:"The farmer’s record book: births, feed and expenses",excerpt:"Simple records reveal production costs, recurring problems and better management decisions.",body:[["What to record","Track animal or group ID, purchases and sales, mating and births, weights, feed, medicines, vaccines, deaths and output. Record date, quantity and price, and keep receipts."],["How to use the data","Calculate feed cost per head or kilogram of gain, birth and mortality rates, and output. Review figures monthly and compare seasons. Keep personal and farm expenses separate."]]}},
{ id:"farm-business",cat:"crops",mins:7,src:[["FAO – Farm business management","https://www.fao.org/family-farming/en/"]],ar:{title:"كيف تبدأ مشروعاً فلاحياً صغيراً دون مخاطرة عمياء؟",excerpt:"ابدأ بدراسة السوق والموارد والتكاليف ثم تجربة صغيرة قابلة للقياس.",body:[["اختبر الفكرة","حدد من سيشتري المنتج وبأي سعر ومتى، ومن هم المنافسون، وكيف ستنقل وتخزن الإنتاج. اسأل مشترين فعليين ولا تعتمد على تقديرات متفائلة فقط."],["احسب قبل الاستثمار","اكتب تكلفة التأسيس والمصاريف المتغيرة والثابتة ورأس المال العامل واحتياط الطوارئ. احسب سيناريو متحفظاً إذا انخفض السعر أو الإنتاج، وابدأ بتجربة صغيرة قبل التوسع."]]},fr:{title:"Lancer une petite activité agricole sans risque aveugle",excerpt:"Étudiez marché, ressources et coûts, puis testez à petite échelle avec des mesures.",body:[["Tester l’idée","Identifiez les acheteurs, prix, périodes de demande, concurrents et moyens de transport et stockage. Interrogez des acheteurs réels et évitez les prévisions trop optimistes."],["Calculer avant d’investir","Listez investissement initial, charges fixes et variables, fonds de roulement et réserve d’urgence. Simulez un scénario prudent avec prix ou rendement plus faibles. Testez à petite échelle avant d’agrandir."]]},en:{title:"Starting a small farm business without blind risk",excerpt:"Study the market, resources and costs, then run a measurable small pilot.",body:[["Test the idea","Identify buyers, prices, demand seasons, competitors and how you will transport and store output. Speak to real buyers and avoid relying only on optimistic estimates."],["Cost before investing","List start-up investment, fixed and variable costs, working capital and an emergency reserve. Model a cautious scenario with lower prices or yields, and pilot on a small scale before expansion."]]}},
{ id:"feed-storage",cat:"ruminants",mins:6,src:[["FAO – Feed resources","https://www.fao.org/animal-production/en/"]],ar:{title:"تخزين الأعلاف والتبن: الوقاية من العفن والهدر",excerpt:"التخزين الجاف والتهوية ورفع العلف عن الأرض تقلل التلف ومخاطر السموم الفطرية.",body:[["مكان التخزين","خزّن التبن والحبوب في مكان جاف جيد التهوية بعيداً عن تسرب المطر والجدران الرطبة. ارفع الرزم عن الأرض واترك مسافات للفحص، واحمِ المخزون من القوارض والطيور."],["الفحص قبل التغذية","افحص اللون والرائحة ووجود الرطوبة أو العفن أو الحشرات. لا تقدّم علفاً متعفناً أو متغير الرائحة للحيوانات، ولا تخلط الجيد بالمتلف لإخفاء المشكلة. راجع المورد عند الاشتباه بتلوث الحبوب."]]},fr:{title:"Stocker fourrages et foin : prévenir moisissures et pertes",excerpt:"Un stockage sec, ventilé et surélevé limite la détérioration et les mycotoxines.",body:[["Lieu de stockage","Stockez foin et céréales dans un endroit sec et ventilé, à l’abri des infiltrations et murs humides. Surélevez les bottes et laissez un accès pour inspection. Protégez des rongeurs et oiseaux."],["Contrôle avant distribution","Vérifiez couleur, odeur, humidité, moisissures et insectes. Ne distribuez pas d’aliment moisi ou d’odeur anormale et ne le mélangez pas au bon aliment pour masquer le défaut. Contactez le fournisseur en cas de suspicion de contamination."]]},en:{title:"Storing feed and hay: preventing mould and waste",excerpt:"Dry, ventilated and raised storage reduces spoilage and mycotoxin risks.",body:[["Storage area","Store hay and grain in a dry, ventilated place protected from leaks and damp walls. Raise bales off the ground and leave inspection access. Protect stores from rodents and birds."],["Check before feeding","Inspect colour, smell, moisture, mould and insects. Do not feed mouldy or off-smelling material, and never dilute spoiled feed with good feed to hide the problem. Contact the supplier if grain contamination is suspected."]]}},
{ id:"poultry-biosecurity",cat:"birds",mins:6,src:[["FAO – Poultry biosecurity","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"الأمن الحيوي في مزارع الدواجن",excerpt:"منع دخول العدوى أسهل من التعامل مع انتشار المرض داخل الحظيرة.",body:[["تنظيم الدخول","قلل الزوار، واستخدم أحذية وملابس مخصصة، ونظف وطهّر المعدات والمركبات حسب الخطة. امنع دخول الطيور البرية والقوارض، ولا تشارك الأدوات بين الحظائر دون تنظيف."],["المراقبة والإبلاغ","راقب استهلاك الماء والعلف والنشاط والنفوق يومياً. اعزل الحالات غير الطبيعية واتصل بالطبيب البيطري سريعاً عند ارتفاع النفوق أو ظهور أعراض جماعية. لا تنقل الطيور أو تبيعها عند الاشتباه بمرض معدٍ قبل التوجيه الرسمي."]]},fr:{title:"Biosécurité dans les élevages avicoles",excerpt:"Empêcher l’introduction d’une infection est plus simple que gérer sa propagation.",body:[["Contrôler les accès","Limitez les visiteurs, utilisez vêtements et chaussures dédiés, nettoyez et désinfectez matériel et véhicules selon le plan. Empêchez l’accès des oiseaux sauvages et rongeurs et nettoyez les outils entre bâtiments."],["Surveillance et signalement","Suivez chaque jour eau, aliment, activité et mortalité. Isolez les sujets anormaux et contactez rapidement le vétérinaire si la mortalité augmente ou si des signes collectifs apparaissent. Ne déplacez ni ne vendez les oiseaux suspects avant avis officiel."]]},en:{title:"Biosecurity on poultry farms",excerpt:"Preventing disease entry is easier than managing an outbreak inside a poultry house.",body:[["Control access","Limit visitors, use dedicated clothing and footwear, and clean and disinfect equipment and vehicles under a plan. Exclude wild birds and rodents, and clean tools between houses."],["Monitor and report","Track water and feed intake, activity and mortality daily. Isolate abnormal birds and contact a veterinarian quickly if mortality rises or flock-wide signs appear. Do not move or sell suspect birds before official guidance."]]}},
{ id:"quail-business",cat:"birds",mins:6,src:[["FAO – Poultry production","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"مشروع تربية السمان: التجهيز والإنتاج والتسويق",excerpt:"صغر المساحة لا يعني غياب التخطيط؛ السوق والعلف والتهوية والتصريف تحدد الجدوى.",body:[["قبل الانطلاق","تحقق من وجود طلب على البيض أو اللحم ومن المشترين والأسعار. جهّز أقفاصاً آمنة جيدة التهوية وسهلة التنظيف، ومشارب تمنع البلل، ومكاناً منفصلاً للصيصان."],["الإدارة والحساب","استخدم علفاً مناسباً للعمر والإنتاج، وسجّل استهلاك العلف والبيض والنفوق. احسب كلفة الطيور والتجهيز والكهرباء والتدفئة والتعبئة والنقل، ولا توسع المشروع قبل اختبار البيع بانتظام."]]},fr:{title:"Projet d’élevage de cailles : équipement, production et marché",excerpt:"Une petite surface ne dispense pas de planifier débouchés, alimentation, ventilation et coûts.",body:[["Avant de démarrer","Vérifiez la demande en œufs ou viande, les acheteurs et les prix. Installez des cages sûres, ventilées et faciles à nettoyer, des abreuvoirs limitant l’humidité et un espace séparé pour les jeunes."],["Conduite et calcul","Utilisez un aliment adapté à l’âge et à la production et notez consommation, ponte et mortalité. Calculez oiseaux, équipements, électricité, chauffage, emballage et transport. N’agrandissez pas avant de valider les ventes régulières."]]},en:{title:"Quail farming project: setup, production and marketing",excerpt:"Small space does not remove the need to plan demand, feed, ventilation and costs.",body:[["Before starting","Check demand for eggs or meat, buyers and prices. Set up safe, ventilated, easy-to-clean cages, drinkers that limit wetness and a separate brooder area."],["Management and costing","Use age- and purpose-appropriate feed and record feed intake, eggs and mortality. Include birds, equipment, power, heating, packaging and transport in costs. Expand only after testing reliable sales."]]}},
{ id:"farm-water",cat:"crops",mins:6,src:[["FAO – Water scarcity and agriculture","https://www.fao.org/land-water/water/water-scarcity/en/"]],ar:{title:"ترشيد استهلاك الماء في المزرعة",excerpt:"إصلاح التسرب واختيار طريقة الري المناسبة وجدولة السقي يقلل الهدر ويحافظ على المحصول.",body:[["قياس الاستهلاك","راقب عداد الماء أو مدة تشغيل المضخة، وافحص الأنابيب والوصلات والمرشحات. سجّل كمية الماء لكل قطعة أو دورة إنتاج حتى تعرف أين يحدث الهدر."],["حلول عملية","استخدم الري بالتنقيط حيث يناسب المحصول والتربة، وغطِّ التربة عند الحاجة لتقليل التبخر، واجمع مياه الأمطار إن كان ذلك آمناً ومسموحاً. لا تستخدم مياهاً غير معالجة على محاصيل تؤكل نيئة دون تقييم صحي."]]},fr:{title:"Économiser l’eau dans l’exploitation agricole",excerpt:"Réparer les fuites, choisir le bon système et programmer l’irrigation réduit le gaspillage.",body:[["Mesurer la consommation","Suivez compteur ou durée de pompage et vérifiez tuyaux, raccords et filtres. Notez les volumes par parcelle ou cycle pour identifier les pertes."],["Solutions pratiques","Utilisez le goutte-à-goutte lorsqu’il convient à la culture et au sol, paillez si utile pour limiter l’évaporation et récupérez l’eau de pluie lorsque c’est sûr et autorisé. N’utilisez pas d’eaux non traitées sur des cultures consommées crues sans évaluation sanitaire."]]},en:{title:"Saving water on the farm",excerpt:"Fixing leaks, choosing suitable irrigation and scheduling watering reduce waste.",body:[["Measure use","Track the water meter or pump running time and inspect pipes, joints and filters. Record water volumes by field or production cycle to identify losses."],["Practical options","Use drip irrigation where suitable for crop and soil, mulch where useful to reduce evaporation and harvest rainwater where safe and permitted. Do not use untreated water on crops eaten raw without a food-safety assessment."]]}},
{ id:"farm-marketing",cat:"crops",mins:6,src:[["FAO – Agricultural marketing","https://www.fao.org/markets-and-trade/en/"]],ar:{title:"تسويق المنتجات الفلاحية: من المزرعة إلى الزبون",excerpt:"التعبئة والجودة والتوقيت ومعرفة المشتري تؤثر في السعر والربح الصافي.",body:[["افهم الزبون","حدد هل ستبيع لتاجر جملة أو متجر أو مطعم أو مباشرة للمستهلك. اسأل عن الحجم والجودة والتعبئة ومواعيد التسليم والكميات المطلوبة قبل الإنتاج."],["احسب السعر الصافي","اطرح من سعر البيع تكاليف الفرز والتعبئة والتبريد والنقل والعمولة والتالف. احتفظ بسجل للمبيعات والعملاء، ولا تعتمد على مشترٍ واحد إذا كان ذلك يعرّض المشروع للخطر."]]},fr:{title:"Commercialiser les produits agricoles : de la ferme au client",excerpt:"Conditionnement, qualité, calendrier et connaissance de l’acheteur influencent le prix net.",body:[["Comprendre le client","Identifiez si vous vendez à un grossiste, magasin, restaurant ou directement au consommateur. Demandez calibre, qualité, emballage, calendrier et volumes avant de produire."],["Calculer le prix net","Déduisez du prix de vente tri, emballage, froid, transport, commission et pertes. Tenez un registre des ventes et clients et évitez de dépendre d’un seul acheteur si cela fragilise l’activité."]]},en:{title:"Marketing farm products: from farm gate to customer",excerpt:"Packaging, quality, timing and buyer requirements affect the net selling price.",body:[["Understand the customer","Decide whether you sell to wholesalers, shops, restaurants or consumers. Confirm size, quality, packaging, delivery timing and volume requirements before production."],["Calculate net price","Subtract grading, packaging, cooling, transport, commission and losses from the selling price. Keep sales and customer records and avoid overdependence on one buyer where possible."]]}},
{ id:"ostrich-care",cat:"birds",mins:6,src:[["FAO – Animal production","https://www.fao.org/animal-production/en/"]],ar:{title:"تربية النعام: المساحة والسياج والتغذية",excerpt:"النعام يحتاج إلى مساحة حركة وسياج آمن وإدارة خاصة للصغار ومتابعة بيطرية.",body:[["الموقع والتجهيز","قبل الاستثمار، تحقق من القوانين والطلب والسوق وتوفر الخبرة. جهّز حظائر واسعة وسياجاً واضحاً وآمناً يقلل اصطدام الطيور، مع مأوى يحمي من الطقس ومكان منفصل للصغار."],["التغذية والصحة","استخدم علائق مخصصة وموزونة حسب العمر، وامنع ابتلاع الأجسام الغريبة. راقب الأرجل والنمو والشهية، واستعن بطبيب بيطري لديه خبرة بالطيور الكبيرة؛ لا تعتمد على وصفات عامة من مزارع أخرى."]]},fr:{title:"Élevage d’autruches : espace, clôtures et alimentation",excerpt:"L’autruche exige espace, clôture sûre, conduite spécifique des jeunes et suivi vétérinaire.",body:[["Site et équipements","Avant d’investir, vérifiez réglementation, débouchés, marché et disponibilité de compétences. Prévoyez de grands enclos, des clôtures visibles et sûres pour limiter les collisions, un abri et un espace séparé pour les jeunes."],["Alimentation et santé","Utilisez des rations équilibrées adaptées à l’âge et empêchez l’ingestion d’objets étrangers. Surveillez pattes, croissance et appétit. Faites appel à un vétérinaire expérimenté avec les grands oiseaux."]]},en:{title:"Ostrich farming: space, fencing and feeding",excerpt:"Ostriches require room to move, safe fencing, special chick management and veterinary support.",body:[["Site and facilities","Before investing, check regulations, market demand and access to experienced support. Provide large enclosures, visible safe fencing to reduce collisions, weather shelter and separate chick areas."],["Feeding and health","Use balanced age-appropriate rations and prevent ingestion of foreign objects. Monitor legs, growth and appetite and work with a veterinarian experienced in large birds; avoid copying generic recipes from other farms."]]}},
{ id:"goat-milk",cat:"ruminants",mins:6,src:[["FAO – Dairy production","https://www.fao.org/dairy-production-products/en/"]],ar:{title:"إنتاج حليب الماعز: النظافة والتغذية والتسويق",excerpt:"نظافة الحلب وتبريد الحليب وسلامة الضرع أساس جودة المنتج وثقة المستهلك.",body:[["روتين الحلب","اغسل اليدين ونظف الضرع وجففه قبل الحلب، واستعمل أوعية وأدوات مخصصة ونظيفة. افحص الحليب بصرياً ولا تخلط الحليب غير الطبيعي مع السليم."],["الحفظ والبيع","برّد الحليب بسرعة إلى درجة مناسبة وفق المتطلبات المحلية، واحفظه في عبوات غذائية نظيفة. تحقق من شروط الترخيص والفحوص والتوسيم، ولا تسوّق الحليب الخام على أنه آمن دون الالتزام بالقواعد الصحية."]]},fr:{title:"Lait de chèvre : hygiène, alimentation et commercialisation",excerpt:"Hygiène de traite, refroidissement et santé mammaire fondent la qualité et la confiance.",body:[["Routine de traite","Lavez les mains, nettoyez et séchez la mamelle avant la traite. Utilisez des récipients propres dédiés. Examinez le lait et ne mélangez pas un lait anormal au lait sain."],["Conservation et vente","Refroidissez rapidement le lait selon les exigences locales et utilisez des contenants alimentaires propres. Vérifiez licences, contrôles et étiquetage. Ne présentez pas le lait cru comme sûr sans respecter les règles sanitaires."]]},en:{title:"Goat milk production: hygiene, feeding and marketing",excerpt:"Milking hygiene, rapid cooling and udder health underpin product quality and consumer trust.",body:[["Milking routine","Wash hands and clean and dry the udder before milking. Use dedicated clean equipment. Inspect milk and keep abnormal milk separate from good milk."],["Storage and sale","Cool milk promptly under local requirements and use clean food-grade containers. Check licensing, testing and labelling rules. Do not market raw milk as safe without meeting food-safety regulations."]]}},
{ id:"dairy-calf",cat:"ruminants",mins:6,src:[["FAO – Animal production","https://www.fao.org/animal-production/en/"]],ar:{title:"رعاية العجول الصغيرة: اللبأ والنظافة والنمو",excerpt:"التغذية المبكرة والنظافة ومراقبة النمو تساعد على تقليل مشاكل العجول.",body:[["الساعات الأولى","يجب أن يحصل العجل حديث الولادة على اللبأ الجيد في الوقت المناسب وبكمية يحددها الإرشاد البيطري، مع التأكد من قدرته على الرضاعة. نظف مكان الولادة وجفف العجل واحمه من البرد."],["المتابعة اليومية","راقب النشاط والشهية والبراز والتنفس، ووفّر ماءً نظيفاً وعلفاً بادئاً مناسباً حسب العمر. نظّف أدوات الحليب بين الاستخدامات وسجّل الوزن والأمراض، واطلب الطبيب عند الإسهال أو الجفاف أو صعوبة التنفس."]]},fr:{title:"Soins aux jeunes veaux : colostrum, hygiène et croissance",excerpt:"Alimentation précoce, hygiène et suivi de croissance aident à réduire les problèmes des veaux.",body:[["Premières heures","Le veau nouveau-né doit recevoir un colostrum de qualité au bon moment et selon les conseils vétérinaires, en vérifiant sa capacité à téter. Nettoyez l’aire de vêlage, séchez le veau et protégez-le du froid."],["Suivi quotidien","Surveillez activité, appétit, fèces et respiration. Fournissez eau propre et aliment de démarrage adapté à l’âge. Nettoyez le matériel lacté et notez poids et maladies. Consultez en cas de diarrhée, déshydratation ou difficulté respiratoire."]]},en:{title:"Young calf care: colostrum, hygiene and growth",excerpt:"Early feeding, hygiene and growth monitoring help reduce common calf problems.",body:[["First hours","A newborn calf should receive good-quality colostrum promptly, following veterinary guidance, and be checked for effective suckling. Clean the calving area, dry the calf and protect it from cold."],["Daily monitoring","Monitor activity, appetite, manure and breathing. Provide clean water and age-appropriate starter feed. Clean milk-feeding equipment between uses and record weight and illness. Seek veterinary help for diarrhoea, dehydration or breathing difficulty."]]}},
{ id:"herbs",cat:"crops",mins:5,src:[["FAO – Plant production","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"زراعة النباتات العطرية والطبية كمشروع صغير",excerpt:"النعناع وإكليل الجبل والزعتر وغيرها تحتاج إلى سوق واضح وتجفيف وتخزين مناسب.",body:[["اختيار النوع والسوق","اختر النوع وفق المناخ والماء والطلب المحلي، وتحقق من وجود مشترين قبل التوسع. استخدم بذوراً أو شتلات موثوقة وتأكد من هوية النبات وعدم خلط الأنواع."],["الحصاد والتجفيف","احصد في توقيت مناسب للجزء المستخدم، وجفف في مكان نظيف مظلل وجيد التهوية بعيداً عن الغبار والمواد الكيميائية. خزّن المنتج الجاف في عبوات محكمة مع بطاقة النوع وتاريخ الحصاد."]]},fr:{title:"Cultiver les plantes aromatiques et médicinales à petite échelle",excerpt:"Menthe, romarin et thym exigent un débouché clair, un séchage et un stockage adaptés.",body:[["Espèce et marché","Choisissez selon climat, eau et demande locale et identifiez des acheteurs avant expansion. Utilisez des semences ou plants fiables et vérifiez l’identité botanique."],["Récolte et séchage","Récoltez au bon stade pour la partie utilisée. Séchez dans un lieu propre, ombragé et ventilé, à l’abri poussière et produits chimiques. Stockez au sec dans des emballages fermés avec nom et date de récolte."]]},en:{title:"Growing aromatic and medicinal plants as a small business",excerpt:"Mint, rosemary and thyme need a clear market and suitable drying and storage.",body:[["Species and market","Choose species to match climate, water and local demand, and identify buyers before scaling up. Use reliable seed or planting material and verify plant identity."],["Harvest and drying","Harvest at the appropriate stage for the part used. Dry in a clean, shaded, ventilated place away from dust and chemicals. Store dry products in sealed packaging labelled with species and harvest date."]]}},
{ id:"soil-salinity",cat:"crops",mins:6,src:[["FAO – Salt-affected soils","https://www.fao.org/global-soil-partnership/areas-of-work/soil-salinity/en/"]],ar:{title:"ملوحة التربة ومياه الري: الأعراض وطرق التعامل",excerpt:"اصفرار النبات وضعف النمو قد يرتبطان بالملوحة، لكن التشخيص يحتاج إلى تحليل.",body:[["التشخيص","قِس ملوحة التربة ومياه الري بتحليل مناسب، وافحص الصرف وعمق الماء الأرضي. لا تعتمد على شكل النبات وحده، لأن أعراض الملوحة قد تتشابه مع نقص العناصر أو مشاكل الجذور."],["الإدارة","حسّن الصرف أولاً، واختر محاصيل وأصنافاً تتحمل مستوى الملوحة الموجود. يمكن أن يساعد الغسل بالماء المناسب عندما يتوفر صرف جيد، لكن الغسل دون صرف قد يزيد المشكلة. استشر مهندساً زراعياً قبل إضافة محسنات التربة."]]},fr:{title:"Salinité du sol et de l’eau : symptômes et gestion",excerpt:"Jaunissement et faible croissance peuvent être liés au sel, mais l’analyse est nécessaire.",body:[["Diagnostic","Analysez la salinité du sol et de l’eau d’irrigation et vérifiez drainage et profondeur de nappe. Les symptômes seuls ne suffisent pas : ils peuvent ressembler à des carences ou problèmes racinaires."],["Gestion","Améliorez d’abord le drainage et choisissez des cultures tolérantes au niveau de salinité. Le lessivage peut aider avec une eau adaptée et un bon drainage ; sans drainage, il peut aggraver la situation. Demandez conseil avant tout amendement."]]},en:{title:"Soil and irrigation-water salinity: symptoms and management",excerpt:"Yellowing and poor growth may relate to salts, but testing is needed for diagnosis.",body:[["Diagnosis","Test soil and irrigation-water salinity and check drainage and water-table depth. Plant symptoms alone are not enough because salinity can resemble nutrient or root problems."],["Management","Improve drainage first and select crops or varieties tolerant of measured salinity. Leaching may help where suitable water and drainage are available; without drainage it can worsen the problem. Seek agronomic advice before applying amendments."]]}},
{ id:"seedlings",cat:"crops",mins:5,src:[["FAO – Plant production and protection","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"إنتاج شتلات سليمة: البذور والمشتل والري",excerpt:"بذور موثوقة ووسط زراعة نظيف وري معتدل تقلل ضعف الشتلات وانتقال الأمراض.",body:[["إعداد المشتل","استخدم بذوراً معروفة المصدر وعبوات نظيفة ووسطاً جيد الصرف. لا تعِد استخدام صوانٍ ملوثة دون تنظيف وتعقيم مناسب، ووفّر ضوءاً وتهوية كافيين."],["الري والتقسية","حافظ على رطوبة متوازنة دون إغراق، وراقب ظهور البادرات يومياً. قبل نقل الشتلات للحقل، عوّدها تدريجياً على ظروف الخارج وفق نوع المحصول والطقس، واستبعد الشتلات الضعيفة أو المصابة."]]},fr:{title:"Produire des plants sains : semences, pépinière et arrosage",excerpt:"Semences fiables, substrat propre et irrigation modérée limitent faiblesse et maladies.",body:[["Préparer la pépinière","Utilisez des semences traçables, des contenants propres et un substrat drainant. Ne réutilisez pas des plateaux contaminés sans nettoyage adapté. Assurez lumière et ventilation."],["Arrosage et endurcissement","Maintenez une humidité régulière sans saturation et observez la levée. Avant transplantation, habituez progressivement les plants aux conditions extérieures selon culture et météo. Écartez les plants faibles ou malades."]]},en:{title:"Producing healthy transplants: seed, nursery and watering",excerpt:"Reliable seed, clean growing media and careful watering reduce weak seedlings and disease.",body:[["Nursery setup","Use traceable seed, clean trays and a well-drained growing medium. Do not reuse contaminated trays without proper cleaning. Provide enough light and ventilation."],["Watering and hardening","Maintain even moisture without waterlogging and monitor emergence daily. Before field transplanting, gradually acclimatize seedlings to outdoor conditions according to crop and weather. Reject weak or diseased plants."]]}},
{ id:"poultry-costs",cat:"birds",mins:6,src:[["FAO – Poultry production","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"حساب تكاليف مشروع الدواجن قبل شراء الصيصان",excerpt:"ثمن الصوص ليس التكلفة كلها؛ العلف والطاقة والفرشة والدواء والتسويق عناصر أساسية.",body:[["التكاليف التي يجب إدراجها","احسب الصيصان والعلف والفرشة والتدفئة والكهرباء والماء واللقاحات والبيطرة والعمال والتطهير والنقل والتعبئة. أضف تكلفة تجهيز الحظيرة واستهلاك المعدات."],["اختبر الربحية","ضع سيناريوهات مختلفة لسعر العلف وسعر البيع ونسبة النفوق ومدة الدورة. لا تعتبر الإيراد ربحاً؛ اطرح كل التكاليف، واحتفظ برأس مال عامل لدورة كاملة واحتياط للطوارئ."]]},fr:{title:"Calculer le coût d’un projet avicole avant l’achat des poussins",excerpt:"Le prix du poussin n’est pas le coût total : aliment, énergie, litière, santé et vente comptent.",body:[["Coûts à inclure","Calculez poussins, aliment, litière, chauffage, électricité, eau, vaccins, vétérinaire, main-d’œuvre, désinfection, transport et emballage. Ajoutez installation et amortissement des équipements."],["Tester la rentabilité","Modélisez plusieurs scénarios de prix d’aliment, prix de vente, mortalité et durée de lot. Le chiffre d’affaires n’est pas le bénéfice : déduisez toutes les charges et prévoyez fonds de roulement et réserve."]]},en:{title:"Calculating poultry project costs before buying chicks",excerpt:"Chick purchase price is not the full cost: feed, energy, litter, health and marketing matter.",body:[["Costs to include","Calculate chicks, feed, litter, heating, electricity, water, vaccines, veterinary care, labour, cleaning, transport and packaging. Include housing setup and equipment depreciation."],["Test profitability","Model different feed prices, sale prices, mortality rates and cycle lengths. Revenue is not profit: subtract every cost and reserve working capital for a full cycle plus emergencies."]]}},
{ id:"fish-business",cat:"fish",mins:6,src:[["FAO – Aquaculture","https://www.fao.org/fishery/en/topic/166235"]],ar:{title:"دراسة جدوى أولية لمشروع تربية الأسماك",excerpt:"الماء والطاقة والعلف والإصبعيات والتسويق قد تجعل المشروع حساساً للتكلفة.",body:[["دراسة الموارد","تحقق من كمية الماء وجودته واستمراريته والطاقة اللازمة للضخ والتهوية. راجع التراخيص والاشتراطات البيئية والبيطرية، وحدد النوع المناسب للظروف المحلية."],["حساب الدورة","احسب الأحواض والمعدات والإصبعيات والعلف والطاقة والعمال والتحاليل والنقل والتبريد. قدّر النفوق والنمو ومدة الدورة وسعر البيع بسيناريو متحفظ، ولا تبدأ قبل وجود خطة تصريف للإنتاج."]]},fr:{title:"Pré-étude de faisabilité d’un projet piscicole",excerpt:"Eau, énergie, aliment, alevins et débouchés rendent le projet sensible aux coûts.",body:[["Étudier les ressources","Vérifiez volume, qualité et continuité de l’eau ainsi que l’énergie de pompage et d’aération. Consultez les autorisations et exigences environnementales et sanitaires, puis choisissez une espèce adaptée."],["Calculer le cycle","Intégrez bassins, équipements, alevins, aliment, énergie, main-d’œuvre, analyses, transport et froid. Estimez mortalité, croissance, durée et prix avec un scénario prudent. Ne démarrez pas sans débouchés identifiés."]]},en:{title:"A first feasibility check for a fish-farming project",excerpt:"Water, energy, feed, fingerlings and market access can make the project cost-sensitive.",body:[["Assess resources","Check water volume, quality and reliability, plus energy for pumping and aeration. Review permits and environmental and health requirements, then select a locally suitable species."],["Cost the production cycle","Include ponds, equipment, fingerlings, feed, energy, labour, testing, transport and cooling. Estimate mortality, growth, cycle length and sale price using a cautious scenario. Secure a market before starting."]]}},
{ id:"pesticide-safety",cat:"crops",mins:6,src:[["FAO/WHO – International Code of Conduct on Pesticide Management","https://www.fao.org/pesticide-management/en/"]],ar:{title:"السلامة عند استعمال المبيدات الزراعية",excerpt:"اختيار المنتج المسجل واتباع الملصق والوقاية الشخصية يحمي العامل والمستهلك والبيئة.",body:[["قبل الرش","تأكد من تشخيص الآفة ومن أن المنتج مسجل للمحصول والهدف في بلدك. اقرأ الملصق كاملاً، وتحقق من الجرعة وفترة ما قبل الحصاد وفترة إعادة الدخول ومعدات الوقاية."],["أثناء وبعد الرش","لا ترش مع الرياح أو قرب مصادر الماء، ولا تأكل أو تشرب أثناء العمل. احفظ العبوات في مكان مقفل ولا تعِد استعمالها، وتخلص منها وفق التعليمات المحلية. لا تخلط المبيدات ولا ترفع الجرعة من تلقاء نفسك."]]},fr:{title:"Sécurité lors de l’utilisation des pesticides agricoles",excerpt:"Produit homologué, étiquette et protection individuelle protègent applicateur, consommateur et environnement.",body:[["Avant traitement","Confirmez le diagnostic et vérifiez que le produit est homologué pour la culture et la cible dans votre pays. Lisez l’étiquette : dose, délai avant récolte, délai de rentrée et équipements de protection."],["Pendant et après","Évitez vent et proximité des eaux ; ne mangez ni ne buvez pendant l’application. Gardez les produits sous clé, ne réutilisez pas les emballages et éliminez-les selon les règles locales. Ne mélangez pas les produits et n’augmentez pas la dose."]]},en:{title:"Safety when using agricultural pesticides",excerpt:"Registered products, label compliance and protective equipment protect workers, consumers and the environment.",body:[["Before spraying","Confirm the pest diagnosis and ensure the product is registered for the crop and target locally. Read the full label, including rate, pre-harvest interval, re-entry period and protective equipment."],["During and after use","Avoid windy conditions and water sources; do not eat or drink while applying. Store products locked away, never reuse containers and dispose of them under local rules. Do not mix products or increase rates on your own."]]}},
{ id:"soil-organic",cat:"crops",mins:5,src:[["FAO – Soil organic carbon","https://www.fao.org/soils-portal/soil-management/soil-organic-carbon/en/"]],ar:{title:"رفع خصوبة التربة بالمادة العضوية والدورة الزراعية",excerpt:"المادة العضوية والغطاء النباتي وتقليل الانجراف تدعم بنية التربة على المدى الطويل.",body:[["بناء المادة العضوية","أعد بقايا النباتات السليمة إلى التربة أو حوّلها إلى كمبوست ناضج، واستخدم محاصيل تغطية حيث تسمح المياه والمناخ. تجنب حرق المخلفات بشكل عشوائي."],["حماية التربة","نوّع المحاصيل وقلل الحرث المفرط وحافظ على غطاء التربة لتقليل الانجراف والتبخر. راقب التغيرات بتحليل دوري ولا تتوقع تحسناً فورياً؛ بناء خصوبة التربة يحتاج وقتاً وإدارة مستمرة."]]},fr:{title:"Améliorer la fertilité par la matière organique et la rotation",excerpt:"Matière organique, couverture végétale et réduction de l’érosion soutiennent la structure du sol.",body:[["Augmenter la matière organique","Restituez les résidus végétaux sains ou compostez-les à maturité. Utilisez des couverts lorsque eau et climat le permettent. Évitez le brûlage incontrôlé des résidus."],["Protéger le sol","Diversifiez les cultures, limitez le travail excessif et maintenez une couverture pour réduire érosion et évaporation. Suivez l’évolution par analyses périodiques ; améliorer la fertilité demande du temps et une gestion continue."]]},en:{title:"Building soil fertility with organic matter and crop rotation",excerpt:"Organic matter, plant cover and erosion control support long-term soil structure.",body:[["Build organic matter","Return healthy plant residues to the soil or compost them fully. Use cover crops where water and climate allow. Avoid uncontrolled residue burning."],["Protect the soil","Diversify crops, reduce excessive tillage and maintain soil cover to limit erosion and evaporation. Track changes with periodic tests; soil fertility improvement takes time and consistent management."]]}},
{ id:"farm-planning",cat:"crops",mins:6,src:[["FAO – Farm business management","https://www.fao.org/family-farming/en/"]],ar:{title:"التخطيط الموسمي للمزرعة: ماذا تزرع ومتى؟",excerpt:"التقويم الزراعي المحلي يربط مواعيد الزراعة والري والعمالة والسوق بالمناخ.",body:[["تقويم المحاصيل","اكتب مواعيد تجهيز الأرض والبذر والشتل والتسميد والري والمكافحة والحصاد لكل محصول. عدّل التواريخ حسب الولاية والارتفاع والأمطار ودرجة الحرارة، لا حسب تقويم موحد."],["تنسيق الموارد","وزع احتياجات العمال والمعدات والماء والسيولة على الموسم، وحدد فترات الذروة مسبقاً. راجع توقعات الطقس ومواعيد السوق، واحتفظ بخطة بديلة عند تأخر الأمطار أو ارتفاع الأسعار."]]},fr:{title:"Planification saisonnière : quoi cultiver et à quel moment ?",excerpt:"Un calendrier local relie semis, irrigation, main-d’œuvre et marché au climat.",body:[["Calendrier cultural","Notez préparation du sol, semis, repiquage, fertilisation, irrigation, protection et récolte pour chaque culture. Ajustez les dates à la wilaya, altitude, pluie et température ; évitez un calendrier unique."],["Coordonner les ressources","Répartissez main-d’œuvre, matériel, eau et trésorerie sur la saison et anticipez les périodes de pointe. Suivez météo et marché et préparez des solutions si les pluies tardent ou les prix changent."]]},en:{title:"Seasonal farm planning: what to grow and when",excerpt:"A local crop calendar links planting, irrigation, labour and markets to climate.",body:[["Crop calendar","Record land preparation, sowing, transplanting, fertilizing, irrigation, crop protection and harvest for each crop. Adjust dates to province, altitude, rainfall and temperature rather than using one national schedule."],["Coordinate resources","Allocate labour, machinery, water and cash across the season and plan for peak periods. Track weather and market timing, and prepare alternatives if rainfall is late or prices change."]]}},
{ id:"sheep-fattening",cat:"sheep",mins:7,src:[["Merck Veterinary Manual – Nutrition of sheep","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep/nutrition-of-sheep"]],ar:{title:"تسمين الخراف: اختيار البداية وقياس النمو والتكلفة",excerpt:"وزن البداية وجودة العلف والتدرج والبيع في الوقت المناسب تحدد نتيجة دورة التسمين.",body:[["اختيار الخراف","اختر خرافاً سليمة ومتقاربة في الوزن والعمر قدر الإمكان، وافحص الأرجل والتنفس والشهية. اعزل المشتريات الجديدة وامنحها وقتاً للتأقلم قبل تغيير العليقة."],["إدارة الدورة","ابدأ بعلف خشن جيد ثم أدخل المركزات تدريجياً وفق تركيبة متوازنة وإرشاد مختص. زن عينة بانتظام، وسجّل استهلاك العلف والوزن والنفوق، واحسب كلفة الكيلوغرام المكتسب وسعر البيع المتوقع."]]},fr:{title:"Engraissement des agneaux : choix, croissance et coût",excerpt:"Poids initial, qualité de la ration, transition progressive et calendrier de vente déterminent le résultat.",body:[["Choisir les animaux","Choisissez des agneaux sains et aussi homogènes que possible en poids et âge. Vérifiez aplombs, respiration et appétit. Isolez les achats et laissez-les s’adapter avant de changer la ration."],["Conduire le cycle","Commencez par un bon fourrage puis introduisez progressivement les concentrés dans une ration équilibrée avec conseil technique. Pesez un échantillon, notez aliment, poids et mortalité, puis calculez coût du gain et prix de vente attendu."]]},en:{title:"Lamb fattening: starting stock, growth and cost tracking",excerpt:"Starting weight, feed quality, gradual transition and sale timing shape finishing results.",body:[["Select lambs","Choose healthy lambs as uniform as practical in weight and age. Check legs, breathing and appetite. Quarantine new arrivals and allow adaptation before changing the ration."],["Manage the cycle","Start with good forage and introduce concentrates gradually within a balanced ration and technical guidance. Weigh a sample, record feed use, weight and mortality, and calculate cost per kilogram gained and expected sale price."]]}},
{ id:"soil-cover",cat:"crops",mins:5,src:[["FAO – Conservation agriculture","https://www.fao.org/conservation-agriculture/en/"]],ar:{title:"حماية التربة من الانجراف والجفاف",excerpt:"الغطاء النباتي ومصدات الرياح وتقليل الحرث تساعد على حفظ التربة والرطوبة.",body:[["تقليل الانجراف","حافظ على بقايا نباتية سليمة أو غطاء نباتي، وازرع على خطوط مناسبة للانحدار، وأنشئ مصدات رياح حيث يلزم. تجنب ترك التربة مكشوفة لفترات طويلة."],["الحفاظ على الرطوبة","استخدم التغطية العضوية والمحاصيل الغطائية عندما تكون مناسبة، وحسّن المادة العضوية والصرف. راقب أثر الممارسات على الرطوبة والمحصول موسمياً وعدّلها حسب نوع التربة."]]},fr:{title:"Protéger le sol contre l’érosion et la sécheresse",excerpt:"Couverture végétale, brise-vent et réduction du travail du sol aident à conserver sol et humidité.",body:[["Limiter l’érosion","Conservez des résidus végétaux sains ou un couvert, travaillez selon des lignes adaptées à la pente et installez des brise-vent si nécessaire. Évitez de laisser le sol nu longtemps."],["Conserver l’humidité","Utilisez paillage et couverts lorsque adaptés, améliorez matière organique et drainage. Évaluez chaque saison l’effet sur humidité et rendement et adaptez les pratiques au type de sol."]]},en:{title:"Protecting soil from erosion and drought",excerpt:"Plant cover, windbreaks and reduced tillage help conserve soil and moisture.",body:[["Reduce erosion","Keep healthy crop residues or plant cover, work along suitable contour lines and use windbreaks where needed. Avoid leaving soil bare for long periods."],["Conserve moisture","Use organic mulch and cover crops where appropriate and improve organic matter and drainage. Assess effects on moisture and yield each season and adapt to soil type."]]}},
{ id:"farm-pricing",cat:"crops",mins:5,src:[["FAO – Agricultural markets","https://www.fao.org/markets-and-trade/en/"]],ar:{title:"تسعير المنتج الفلاحي: لا تخلط بين المبيعات والربح",excerpt:"السعر الجيد يجب أن يغطي التكلفة الكاملة ويأخذ في الاعتبار الجودة والموسم والمنافسة.",body:[["احسب التكلفة الحقيقية","اجمع المدخلات والعمل والماء والطاقة والتعبئة والنقل والتالف والعمولات، وأضف نصيب الوحدة من تكاليف المعدات والبناء. احسب تكلفة الكيلوغرام أو البيضة أو الرأس حسب المنتج."],["حدد السعر والهدف","قارن أسعار السوق وجودة منتجك وموعد البيع. حدّد هامشاً يغطي المخاطر ولا تبنِ القرار على أعلى سعر سمعته. حدّث الحساب كلما تغير سعر العلف أو الوقود أو المدخلات."]]},fr:{title:"Fixer le prix agricole : distinguer ventes et bénéfice",excerpt:"Un bon prix couvre le coût complet et tient compte qualité, saison et concurrence.",body:[["Calculer le coût réel","Additionnez intrants, travail, eau, énergie, emballage, transport, pertes et commissions, puis répartissez équipements et bâtiments. Calculez coût par kilo, œuf ou animal."],["Fixer prix et objectif","Comparez marché, qualité et période de vente. Définissez une marge couvrant les risques sans vous baser sur le prix le plus élevé entendu. Actualisez le calcul lorsque aliment, carburant ou intrants changent."]]},en:{title:"Pricing farm products: do not confuse sales with profit",excerpt:"A sound price covers full costs and reflects quality, season and competition.",body:[["Calculate the real cost","Add inputs, labour, water, energy, packaging, transport, losses and commissions, and allocate equipment and building costs. Calculate cost per kilogram, egg or animal."],["Set price and target","Compare market prices, product quality and sale timing. Set a margin that covers risk rather than relying on the highest price you have heard. Update calculations when feed, fuel or input prices change."]]}},
{ id:"quarantine",cat:"sheep",mins:5,src:[["Merck Veterinary Manual – Preventive health care","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep"]],ar:{title:"عزل الحيوانات الجديدة قبل إدخالها إلى القطيع",excerpt:"فترة العزل والفحص تمنح فرصة لاكتشاف المرض قبل انتقاله إلى بقية الحيوانات.",body:[["طريقة العزل","ضع الحيوان الجديد في مكان منفصل مع أدوات ومشارب ومعالف خاصة، وامنع التلامس المباشر ومشاركة الروث أو المعدات. مدة العزل والفحوص يحددها الطبيب البيطري حسب النوع ومصدر الحيوان ومخاطر المنطقة."],["المتابعة والسجلات","راقب الحرارة والشهية والتنفس والبراز والجلد، وسجّل أي علاج أو لقاح. لا تدمج الحيوان مع القطيع حتى تنتهي فترة العزل ويوافق المختص. طبّق مبدأ العزل أيضاً عند عودة الحيوانات من الأسواق أو المعارض."]]},fr:{title:"Mettre les nouveaux animaux en quarantaine avant intégration",excerpt:"Quarantaine et examen permettent de repérer une maladie avant sa diffusion au troupeau.",body:[["Organisation de la quarantaine","Installez le nouvel animal dans un espace séparé avec matériel, abreuvoirs et mangeoires dédiés. Évitez contact direct et partage de fumier ou d’équipement. Durée et examens sont définis par le vétérinaire selon espèce, origine et risque local."],["Suivi et registres","Surveillez température, appétit, respiration, fèces et peau et notez soins et vaccins. N’intégrez pas l’animal avant la fin de la quarantaine et l’accord du professionnel. Appliquez aussi ce principe au retour de marchés ou expositions."]]},en:{title:"Quarantining new animals before joining the herd",excerpt:"Quarantine and examination can identify disease before it spreads to resident stock.",body:[["Set up quarantine","Keep new animals in a separate area with dedicated equipment, drinkers and feeders. Prevent direct contact and shared manure or tools. A veterinarian should set duration and checks based on species, source and local risks."],["Monitor and record","Observe temperature, appetite, breathing, manure and skin, and record treatments and vaccines. Do not mix animals until quarantine is complete and the professional agrees. Apply the same principle to animals returning from markets or shows."]]}},
{ id:"sheep-body-condition",cat:"sheep",mins:5,src:[["Merck Veterinary Manual – Sheep nutrition","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep/nutrition-of-sheep"]],ar:{title:"تقييم الحالة الجسمية للنعاج قبل الحمل والولادة",excerpt:"متابعة حالة الجسم تساعد على تعديل التغذية واكتشاف النعاج الضعيفة أو السمينة.",body:[["الفحص باليد والعين","قيّم تغطية العضلات حول الظهر والعمود الفقري والأضلاع، ولا تعتمد على الصوف وحده. استخدم مقياس الحالة الجسمية المعتمد محلياً وسجّل النتيجة لكل نعجة."],["تعديل الإدارة","افصل النعاج الضعيفة أو السمينة في مجموعات تغذية مناسبة، وراجع جودة العلف والطفيليات والأسنان والحالة الصحية. التقييم قبل التلقيح وخلال الحمل يساعد على التخطيط، لكن أي تعديل كبير في العليقة يجب أن يكون تدريجياً وبإرشاد مختص."]]},fr:{title:"Évaluer l’état corporel des brebis avant gestation et agnelage",excerpt:"Le suivi de l’état corporel aide à ajuster la ration et repérer brebis maigres ou trop grasses.",body:[["Évaluation","Palpez et observez les muscles autour du dos, de la colonne et des côtes ; la laine seule est trompeuse. Utilisez une échelle d’état corporel reconnue localement et notez chaque brebis."],["Adapter la conduite","Séparez les brebis maigres ou trop grasses en lots alimentaires adaptés et vérifiez fourrage, parasites, dents et santé. Une évaluation avant lutte et pendant gestation aide à planifier ; tout changement important de ration doit être progressif et conseillé."]]},en:{title:"Assessing ewe body condition before pregnancy and lambing",excerpt:"Body condition monitoring helps adjust feeding and identify thin or over-conditioned ewes.",body:[["Assess by touch and sight","Check muscle cover around the back, spine and ribs; wool alone can mislead. Use a locally accepted body-condition scoring system and record each ewe."],["Adjust management","Group thin or over-conditioned ewes for suitable feeding and review forage, parasites, teeth and health. Scoring before mating and during pregnancy supports planning; make major ration changes gradually with technical advice."]]}},
{ id:"farm-energy",cat:"crops",mins:5,src:[["FAO – Energy in agriculture","https://www.fao.org/energy/en/"]],ar:{title:"ترشيد الطاقة في المزرعة وخفض تكاليف التشغيل",excerpt:"صيانة المضخات والتوقيت المناسب ومراقبة الاستهلاك تقلل فاتورة الطاقة.",body:[["مراجعة الاستهلاك","سجّل استهلاك الكهرباء والوقود لكل نشاط، وافحص المضخات والمحركات والفلاتر والتسربات. المعدات غير المصانة قد تستهلك طاقة أكثر وتتعطل في وقت حساس."],["تحسين التشغيل","شغّل المضخات وفق الحاجة وجدول الري، وتجنب التشغيل دون حمل، واستخدم إضاءة مناسبة ومؤقتات حيث تلائم. قارن تكلفة البدائل قبل شراء معدات جديدة، وراعِ السلامة الكهربائية والتهوية."]]},fr:{title:"Économiser l’énergie à la ferme et réduire les charges",excerpt:"Entretien des pompes, bon calendrier et suivi de consommation réduisent la facture énergétique.",body:[["Suivre la consommation","Notez électricité et carburant par activité. Vérifiez pompes, moteurs, filtres et fuites. Un équipement mal entretenu consomme davantage et peut tomber en panne au mauvais moment."],["Optimiser le fonctionnement","Faites fonctionner les pompes selon les besoins et le calendrier d’irrigation, évitez la marche à vide et utilisez éclairage ou minuteries adaptés. Comparez les coûts avant achat et respectez sécurité électrique et ventilation."]]},en:{title:"Saving energy on the farm and reducing operating costs",excerpt:"Pump maintenance, good scheduling and consumption tracking can reduce energy bills.",body:[["Track consumption","Record electricity and fuel by activity and inspect pumps, motors, filters and leaks. Poorly maintained equipment can use more energy and fail at critical times."],["Improve operation","Run pumps according to actual need and irrigation schedules, avoid idle operation and use suitable lighting or timers. Compare lifecycle costs before buying equipment and maintain electrical and ventilation safety."]]}},
{ id:"poultry-heat",cat:"birds",mins:5,src:[["FAO – Poultry production","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"حماية الدواجن من الإجهاد الحراري في الصيف",excerpt:"الظل والتهوية والماء البارد نسبياً وتقليل المناولة تساعد على مواجهة الحر.",body:[["إجراءات الحظيرة","حسّن حركة الهواء والظل، وتأكد من توفر ماء نظيف باستمرار ونظافة المشارب. تجنب الازدحام وخفف الأعمال والمناولة في ساعات الحر الشديد."],["المراقبة","راقب اللهاث ومد الأجنحة والخمول وانخفاض استهلاك العلف. عند ظهور علامات شديدة أو نفوق، اتصل بالطبيب البيطري فوراً. لا تضف أملاحاً أو أدوية إلى الماء دون توجيه مناسب."]]},fr:{title:"Protéger les volailles du stress thermique en été",excerpt:"Ombre, ventilation, eau disponible et réduction des manipulations aident en période chaude.",body:[["Mesures dans le bâtiment","Améliorez circulation d’air et ombrage, assurez une eau propre en permanence et nettoyez les abreuvoirs. Évitez surdensité et manipulations aux heures les plus chaudes."],["Surveillance","Observez halètement, ailes écartées, abattement et baisse de consommation. En cas de signes sévères ou mortalité, contactez immédiatement le vétérinaire. N’ajoutez pas sels ou médicaments dans l’eau sans conseil."]]},en:{title:"Protecting poultry from summer heat stress",excerpt:"Shade, airflow, constant water and reduced handling help birds cope with heat.",body:[["House measures","Improve airflow and shade, keep clean water available at all times and maintain drinkers. Avoid overcrowding and reduce handling during the hottest hours."],["Monitoring","Watch for panting, spread wings, lethargy and reduced feed intake. Contact a veterinarian immediately for severe signs or deaths. Do not add salts or medicines to water without appropriate guidance."]]}},
{ id:"orchard-pruning",cat:"crops",mins:6,src:[["FAO – Fruit tree production","https://www.fao.org/plant-production-protection/en/"]],ar:{title:"مبادئ تقليم الأشجار المثمرة حسب النوع والعمر",excerpt:"التقليم يهدف إلى بناء هيكل متوازن وإزالة الخشب الميت، وليس تقصير الشجرة عشوائياً.",body:[["هدف التقليم","حدد الهدف أولاً: تشكيل شجرة صغيرة، إزالة فروع ميتة أو متقاطعة، تجديد شجرة مثمرة أو تحسين الضوء والتهوية. تختلف مواعيد وشدة التقليم حسب النوع والمناخ وحالة الشجرة."],["الأدوات والسلامة","استخدم أدوات حادة ونظيفة، ولا تزل نسبة كبيرة من المجموع الخضري دفعة واحدة. تجنب التقليم أثناء ظروف تزيد انتشار الأمراض، واستشر مختصاً للأشجار الكبيرة أو المصابة."]]},fr:{title:"Principes de taille des arbres fruitiers selon espèce et âge",excerpt:"La taille vise une structure équilibrée et l’élimination du bois mort, pas une réduction arbitraire.",body:[["Objectif de la taille","Définissez l’objectif : formation d’un jeune arbre, suppression de bois mort ou croisé, renouvellement ou amélioration lumière et aération. Dates et intensité varient selon espèce, climat et état."],["Outils et sécurité","Utilisez des outils propres et affûtés et évitez de retirer une grande part de feuillage en une fois. Évitez les périodes favorables à la propagation des maladies et demandez conseil pour arbres grands ou malades."]]},en:{title:"Fruit-tree pruning principles by species and age",excerpt:"Pruning builds balanced structure and removes dead wood; it is not random tree shortening.",body:[["Purpose of pruning","Define the goal: train a young tree, remove dead or crossing branches, renew fruiting wood or improve light and airflow. Timing and intensity vary by species, climate and tree condition."],["Tools and safety","Use clean, sharp tools and avoid removing too much canopy at once. Avoid conditions that favour disease spread and seek expert help for large or diseased trees."]]}},
{ id:"farm-risk",cat:"crops",mins:5,src:[["FAO – Risk management in agriculture","https://www.fao.org/risk-management/en/"]],ar:{title:"إدارة مخاطر المشروع الفلاحي: ماذا لو تغيّر السعر أو الطقس؟",excerpt:"خطة الطوارئ والاحتياط المالي وتنويع مصادر البيع تقلل أثر المفاجآت.",body:[["حدد المخاطر","اكتب المخاطر المحتملة: الجفاف والحرارة والمرض وارتفاع العلف والوقود وانخفاض سعر البيع وتعطل المعدات. قيّم احتمال كل خطر وأثره، وحدد مؤشرات إنذار مبكر."],["استعد مسبقاً","احتفظ باحتياط نقدي معقول، وصيانة وقائية وموردين بدلاء وخطة ماء وطاقة وطبيب بيطري أو مهندس تتواصل معه. لا توسع الدين قبل اختبار التدفقات النقدية في سيناريو متحفظ."]]},fr:{title:"Gérer les risques agricoles : si prix ou météo changent ?",excerpt:"Plan d’urgence, réserve financière et diversification des ventes limitent les surprises.",body:[["Identifier les risques","Listez sécheresse, chaleur, maladies, hausse des aliments et carburants, baisse des prix et panne d’équipement. Évaluez probabilité et impact et définissez des signaux d’alerte."],["Se préparer","Gardez une réserve financière raisonnable, prévoyez maintenance, fournisseurs alternatifs, solutions d’eau et d’énergie et contacts techniques. N’augmentez pas l’endettement avant d’avoir testé la trésorerie dans un scénario prudent."]]},en:{title:"Managing farm business risks: what if prices or weather change?",excerpt:"Contingency plans, cash reserves and diversified buyers reduce the impact of surprises.",body:[["Identify risks","List drought, heat, disease, higher feed and fuel costs, lower sale prices and equipment failure. Assess likelihood and impact and define early warning signs."],["Prepare in advance","Keep a reasonable cash reserve, schedule preventive maintenance, identify backup suppliers and water and energy options, and maintain technical contacts. Avoid expanding debt before testing cash flow under a cautious scenario."]]}},
{ id:"poultry-waste",cat:"birds",mins:5,src:[["FAO – Poultry production","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"إدارة فرشة وروث الدواجن بطريقة صحية",excerpt:"الرطوبة والروائح والذباب مؤشرات على خلل في التهوية أو التسرب أو كثافة التربية.",body:[["داخل الحظيرة","حافظ على فرشة جافة ومفككة، وأصلح تسرب المشارب وحسّن التهوية. أزل المناطق المبتلة بسرعة وتعامل مع النافق وفق تعليمات الصحة البيطرية."],["التخزين والاستفادة","خزّن الروث بعيداً عن الآبار ومجاري المياه ومناطق العلف، وغطّه بطريقة تمنع الجريان والذباب. لا تستخدمه على المحاصيل الغذائية قبل معالجته وتحلله وفق القواعد المحلية."]]},fr:{title:"Gérer la litière et les fientes de volailles sainement",excerpt:"Humidité, odeurs et mouches peuvent signaler ventilation, fuite ou densité inadéquates.",body:[["Dans le bâtiment","Maintenez une litière sèche et aérée, réparez les fuites d’abreuvoirs et améliorez la ventilation. Retirez rapidement les zones humides et gérez les cadavres selon les consignes sanitaires."],["Stockage et valorisation","Stockez les fientes loin des puits, eaux et aliments, en évitant ruissellement et mouches. Ne les utilisez pas sur cultures alimentaires avant traitement et compostage conformes aux règles locales."]]},en:{title:"Managing poultry litter and manure safely",excerpt:"Wet litter, odours and flies can indicate ventilation, leakage or stocking-density problems.",body:[["Inside the house","Keep litter dry and friable, repair drinker leaks and improve ventilation. Remove wet patches promptly and handle dead birds under veterinary health guidance."],["Storage and use","Store manure away from wells, waterways and feed, preventing runoff and flies. Do not apply to food crops before appropriate treatment and composting under local rules."]]}},
{ id:"farm-marketing-products",cat:"crops",mins:5,src:[["FAO – Agricultural marketing","https://www.fao.org/markets-and-trade/en/"]],ar:{title:"التعبئة والتخزين بعد الحصاد لتقليل خسائر المنتجات",excerpt:"الفرز والتبريد والعبوات المناسبة تقلل التلف وتحافظ على القيمة التسويقية.",body:[["الفرز والتعبئة","افصل الثمار المتضررة، وتجنب الرمي والضغط الزائد. استخدم عبوات نظيفة تسمح بالتهوية وتناسب وزن المنتج والنقل، ولا تخلط درجات الجودة دون توضيح."],["التخزين والنقل","احفظ كل محصول في درجة حرارة ورطوبة تناسبه؛ لا توجد درجة واحدة لكل المنتجات. قلل زمن الانتظار في الشمس، ونظف وسائل النقل وسجّل الكميات المرفوضة وأسباب التلف."]]},fr:{title:"Conditionnement et stockage après récolte pour réduire les pertes",excerpt:"Tri, refroidissement et emballages adaptés limitent les pertes et préservent la valeur commerciale.",body:[["Tri et emballage","Séparez les produits abîmés et évitez chocs et compression. Utilisez des emballages propres, ventilés et adaptés au poids et au transport. Ne mélangez pas les calibres sans indication."],["Stockage et transport","Respectez température et humidité propres à chaque produit ; une seule consigne ne convient pas à tous. Réduisez l’attente au soleil, nettoyez les véhicules et notez rejets et causes de pertes."]]},en:{title:"Post-harvest packing and storage to reduce farm losses",excerpt:"Sorting, cooling and suitable packaging reduce spoilage and preserve market value.",body:[["Sorting and packing","Separate damaged produce and avoid rough handling or excess compression. Use clean, ventilated packaging suited to product weight and transport. Keep grades separate or label them clearly."],["Storage and transport","Use temperature and humidity conditions suited to each crop; there is no single setting for all produce. Minimize waiting in direct sun, clean vehicles and record rejected quantities and causes."]]}},
{ id:"farm-planning-budget",cat:"crops",mins:6,src:[["FAO – Farm business management","https://www.fao.org/family-farming/en/"]],ar:{title:"إعداد ميزانية موسم زراعي قبل شراء البذور والأسمدة",excerpt:"ميزانية المحصول تجمع تكاليف المدخلات والعمالة والماء والطاقة والحصاد والتسويق.",body:[["بنود الميزانية","احسب البذور والشتلات والأسمدة والمبيدات والري والوقود والعمالة والآلات والكراء والحصاد والفرز والنقل. ميّز بين ما تدفعه مرة واحدة وما يتكرر خلال الموسم."],["تقدير العائد","استخدم إنتاجية واقعية من سجلات محلية، واضربها في سعر بيع متحفظ، ثم اطرح التكاليف. جرّب سيناريو انخفاض الإنتاج أو السعر، ولا تنسَ تكلفة التمويل وفترة انتظار تحصيل المبيعات."]]},fr:{title:"Établir le budget d’une campagne avant d’acheter semences et engrais",excerpt:"Le budget inclut intrants, travail, eau, énergie, récolte et commercialisation.",body:[["Postes budgétaires","Calculez semences, plants, engrais, produits phytosanitaires, irrigation, carburant, main-d’œuvre, machines, location, récolte, tri et transport. Distinguez investissement ponctuel et charges saisonnières."],["Estimer le revenu","Utilisez un rendement réaliste issu de références locales et un prix prudent, puis déduisez les charges. Testez une baisse de rendement ou de prix et incluez financement et délai d’encaissement."]]},en:{title:"Budgeting a crop season before buying seed and fertilizer",excerpt:"A crop budget includes inputs, labour, water, energy, harvest and marketing costs.",body:[["Budget items","Include seed, transplants, fertilizer, crop protection, irrigation, fuel, labour, machinery, rent, harvest, grading and transport. Separate one-off investment from seasonal costs."],["Estimate returns","Use realistic local yield records and a cautious selling price, then subtract costs. Test lower-yield or lower-price scenarios and include financing and the time before sales are paid."]]}},
{ id:"sheep-water",cat:"sheep",mins:5,src:[["Merck Veterinary Manual – Sheep nutrition","https://www.merckvetmanual.com/management-and-nutrition/preventative-health-care-and-husbandry-of-sheep/nutrition-of-sheep"]],ar:{title:"أهمية الماء للأغنام وكيفية إدارة المشارب",excerpt:"قلة الماء أو تلوثه يؤثران في الشهية والهضم والإنتاج، خصوصاً في الحر والرضاعة.",body:[["توفير الماء","وفّر ماءً نظيفاً متاحاً باستمرار، مع زيادة الانتباه في الحر وأثناء الرضاعة والتغذية الجافة. تختلف الكمية حسب الوزن والطقس والعلف والحالة الإنتاجية."],["نظافة المشارب","نظف المشارب بانتظام وافحص التسرب والطحالب وتراكم الرواسب. ضعها في مكان يسهل الوصول إليه ولا يسمح بتلوثها بالروث. إذا انخفض شرب القطيع فجأة فافحص جودة الماء وصحة الحيوانات."]]},fr:{title:"L’eau chez les ovins : gérer les abreuvoirs",excerpt:"Manque ou contamination de l’eau affectent appétit, digestion et production, surtout par chaleur et lactation.",body:[["Fournir de l’eau","Laissez de l’eau propre disponible en permanence, avec une attention accrue par forte chaleur, en lactation et avec des aliments secs. Les besoins varient selon poids, météo, ration et stade."],["Hygiène des abreuvoirs","Nettoyez régulièrement et vérifiez fuites, algues et dépôts. Placez les abreuvoirs dans un endroit accessible et protégé des déjections. Si la consommation baisse soudainement, contrôlez eau et santé."]]},en:{title:"Water for sheep: managing drinking systems",excerpt:"Insufficient or contaminated water affects appetite, digestion and production, especially in heat and lactation.",body:[["Provide water","Keep clean water available at all times, with extra attention in hot weather, during lactation and on dry diets. Needs vary with weight, weather, feed and production stage."],["Drinker hygiene","Clean drinkers regularly and check leaks, algae and sediment. Place them where sheep can reach them without manure contamination. If flock water intake suddenly falls, check water quality and animal health."]]}},
{ id:"farm-diversification",cat:"crops",mins:5,src:[["FAO – Family farming","https://www.fao.org/family-farming/en/"]],ar:{title:"تنويع مصادر الدخل في المزرعة الصغيرة",excerpt:"الجمع المدروس بين المحاصيل والتربية والخدمات قد يوزع المخاطر ويحسن استغلال الموارد.",body:[["اختيار الأنشطة","اختر أنشطة تتكامل في الموارد والوقت، مثل استخدام بقايا نباتية آمنة كعلف بعد تقييمها أو تحويل السماد العضوي إلى محسن تربة. لا تستخدم مخلفات ملوثة أو غير مناسبة."],["اختبر قبل التوسع","احسب سوق كل منتج والعمل الإضافي والمعدات والاشتراطات الصحية. ابدأ بنشاط إضافي صغير، وقِس الربح الصافي والوقت والماء قبل إضافة نشاط آخر."]]},fr:{title:"Diversifier les revenus d’une petite exploitation",excerpt:"Associer cultures, élevage et services de façon raisonnée peut répartir les risques et mieux utiliser les ressources.",body:[["Choisir les activités","Sélectionnez des activités complémentaires en ressources et calendrier, par exemple valoriser des résidus végétaux sûrs après évaluation ou composter le fumier. N’utilisez pas de déchets contaminés ou inadaptés."],["Tester avant d’agrandir","Calculez marché, travail supplémentaire, équipements et exigences sanitaires de chaque produit. Commencez petit et mesurez bénéfice net, temps et eau avant d’ajouter une autre activité."]]},en:{title:"Diversifying income on a small farm",excerpt:"Well-planned combinations of crops, livestock and services can spread risk and use resources better.",body:[["Choose complementary activities","Select activities that complement each other in resources and timing, such as safely using suitable crop residues as feed or composting manure. Do not use contaminated or unsuitable waste."],["Pilot before expansion","Calculate the market, extra labour, equipment and health requirements for each product. Start with a small additional activity and measure net return, time and water before adding another."]]}},
{ id:"farm-safety",cat:"crops",mins:5,src:[["FAO – Occupational safety and health in agriculture","https://www.fao.org/rural-employment/work-areas/occupational-safety-and-health/en/"]],ar:{title:"السلامة المهنية في المزرعة: حماية العمال والأطفال",excerpt:"الآلات والحيوانات والمواد الكيميائية والآبار مصادر خطر تحتاج إلى قواعد واضحة.",body:[["تنظيم المكان","أبعد الأطفال عن الآلات والحظائر ومناطق المبيدات والآبار. غطِّ الحفر والخزانات، وثبّت الأسلاك، وضع أدوات الإسعاف وأرقام الطوارئ في مكان معروف."],["العمل الآمن","استخدم معدات الوقاية المناسبة، وأوقف الآلة قبل تنظيفها أو صيانتها، ولا تدخل خزانات أو أماكن مغلقة دون إجراءات مختصة. درّب العمال على التعامل الهادئ مع الحيوانات والرفع الصحيح للأحمال."]]},fr:{title:"Sécurité au travail à la ferme : protéger travailleurs et enfants",excerpt:"Machines, animaux, produits chimiques et puits nécessitent des règles de sécurité claires.",body:[["Organiser les lieux","Éloignez les enfants des machines, bâtiments d’élevage, pesticides et puits. Couvrez fosses et réservoirs, sécurisez câbles et installations, et placez trousse de secours et numéros d’urgence à portée."],["Travailler en sécurité","Portez les protections adaptées, arrêtez les machines avant nettoyage ou maintenance et n’entrez pas dans cuves ou espaces confinés sans procédure spécialisée. Formez les travailleurs à la manipulation calme des animaux et au levage sûr."]]},en:{title:"Farm occupational safety: protecting workers and children",excerpt:"Machinery, animals, chemicals and wells require clear safety rules.",body:[["Organize the site","Keep children away from machinery, livestock areas, pesticides and wells. Cover pits and tanks, secure electrical systems and keep first-aid supplies and emergency contacts accessible."],["Work safely","Use appropriate protective equipment, stop machinery before cleaning or maintenance and never enter tanks or confined spaces without specialist procedures. Train workers in calm animal handling and safe lifting."]]}},

{ id:"pigeons",cat:"birds",mins:5,src:[["FAO – Poultry production and health","https://www.fao.org/poultry-production-products/en/"]],ar:{title:"تربية الحمام: اختيار الأزواج والعش والتغذية",excerpt:"النظافة والتهوية وتسجيل الفقس وفصل الطيور الجديدة أساس إدارة حمام صحي.",body:[["المسكن والأزواج","جهّز مسكناً جافاً جيد التهوية يحمي من القطط والقوارض والطيور البرية. اختر أزواجاً نشيطة وسليمة، ووفّر أعشاشاً نظيفة ومكاناً للراحة، ولا تزدحم الطيور في مساحة صغيرة."],["الغذاء والصحة","قدّم خلطة حبوب مناسبة وماءً نظيفاً ومصدراً آمناً للمعادن حسب الإرشاد الفني. نظّف المشارب والأعشاش وسجّل وضع البيض والفقس والفطام. اعزل الطيور الجديدة والمريضة واستشر البيطري عند النفوق أو الأعراض الجماعية."]]},fr:{title:"Élevage de pigeons : couples, nids et alimentation",excerpt:"Hygiène, ventilation et suivi des éclosions sont essentiels à un élevage sain.",body:[["Logement et couples","Prévoyez un pigeonnier sec et ventilé, protégé des chats, rongeurs et oiseaux sauvages. Choisissez des couples actifs et sains, fournissez des nids propres et évitez la surdensité."],["Alimentation et santé","Distribuez un mélange de graines adapté, de l’eau propre et une source minérale sûre selon les conseils techniques. Nettoyez abreuvoirs et nids, notez ponte, éclosion et sevrage. Isolez nouveaux sujets et malades."]]},en:{title:"Pigeon keeping: pairs, nesting and feeding",excerpt:"Hygiene, ventilation and hatch records are central to healthy pigeon management.",body:[["Housing and pairs","Provide a dry, ventilated loft protected from cats, rodents and wild birds. Select active, healthy pairs, offer clean nest spaces and avoid overcrowding."],["Feed and health","Provide a suitable grain mix, clean water and a safe mineral source according to technical guidance. Clean drinkers and nests and record laying, hatching and weaning. Quarantine new or sick birds and seek veterinary help for deaths or flock-wide signs."]]}},
{ id:"equids",cat:"working",mins:6,src:[["FAO – Animal production and health","https://www.fao.org/animal-production/en/"]],ar:{title:"رعاية الخيول والحمير والبغال في المزرعة",excerpt:"الحوافر والمأوى والماء والتغذية والعمل المتدرج أساس صحة حيوانات العمل.",body:[["المأوى والحوافر","وفّر مأوى جافاً وظلاً وماءً نظيفاً، وأرضية غير زلقة ومساحة للحركة. افحص الحوافر والجلد والظهر ومناطق الاحتكاك من السرج أو الحمولة، واستعن بمختص لتقليم الحوافر عند الحاجة."],["التغذية والعمل","اعتمد على علف خشن جيد وماء متاح، وعدّل كمية العلف حسب الوزن والعمل والحالة الجسمية. زِد الجهد تدريجياً، وامنح فترات راحة، ولا تحمّل الحيوان فوق طاقته. اطلب الطبيب عند العرج أو المغص أو الجروح."]]},fr:{title:"Soins aux chevaux, ânes et mulets à la ferme",excerpt:"Sabots, abri, eau, alimentation et effort progressif sont essentiels aux animaux de travail.",body:[["Abri et sabots","Fournissez abri sec, ombre, eau propre, sol non glissant et espace de mouvement. Examinez sabots, peau, dos et zones de frottement du harnachement. Faites intervenir un professionnel pour l’entretien des sabots."],["Alimentation et travail","Basez la ration sur un bon fourrage et de l’eau disponible, ajustée au poids, travail et état corporel. Augmentez l’effort progressivement, prévoyez du repos et évitez toute surcharge. Consultez en cas de boiterie, colique ou blessure."]]},en:{title:"Caring for horses, donkeys and mules on the farm",excerpt:"Hooves, shelter, water, feeding and gradual workloads support working-animal welfare.",body:[["Shelter and hooves","Provide dry shelter, shade, clean water, non-slip flooring and room to move. Check hooves, skin, back and harness rub areas. Use a qualified professional for hoof care when needed."],["Feeding and work","Base the diet on good forage and available clean water, adjusted to body weight, workload and condition. Increase work gradually, allow rest and never overload the animal. Seek veterinary care for lameness, colic or wounds."]]}}

];
